fn scoped_code_review_theme_id(
    repository: &str,
    pull_number: i64,
    theme_id: &str,
    existing_theme_ids: &HashSet<String>,
) -> String {
    let scope_prefix = format!("{repository}#{pull_number}:");
    if existing_theme_ids.contains(theme_id) || theme_id.starts_with(&scope_prefix) {
        theme_id.to_owned()
    } else {
        format!("{scope_prefix}{theme_id}")
    }
}

fn staged_code_review_theme_ids(
    tx: &rusqlite::Transaction<'_>,
    job_id: &str,
) -> Result<Vec<String>> {
    let mut stmt = tx.prepare(
        "SELECT theme_id FROM code_review_theme_observations WHERE job_id = ?1
         UNION
         SELECT theme_id FROM code_review_finding_themes WHERE linked_by_job_id = ?1
         UNION
         SELECT link.theme_id
         FROM code_review_finding_themes link
         JOIN code_review_findings finding ON finding.id = link.finding_id
         WHERE finding.job_id = ?1",
    )?;
    Ok(stmt
        .query_map(params![job_id], |row| row.get::<_, String>(0))?
        .collect::<rusqlite::Result<Vec<_>>>()?)
}

fn delete_orphan_code_review_themes(
    tx: &rusqlite::Transaction<'_>,
    theme_ids: Vec<String>,
) -> Result<()> {
    for theme_id in theme_ids {
        tx.execute(
            "DELETE FROM code_review_themes
             WHERE id = ?1
               AND NOT EXISTS (
                 SELECT 1 FROM code_review_theme_observations WHERE theme_id = ?1
               )
               AND NOT EXISTS (
                 SELECT 1 FROM code_review_finding_themes WHERE theme_id = ?1
               )
               AND NOT EXISTS (
                 SELECT 1 FROM code_review_theme_transitions WHERE theme_id = ?1
               )",
            params![theme_id],
        )?;
    }
    Ok(())
}

fn publish_code_review_theme_observations(
    tx: &rusqlite::Transaction<'_>,
    job_id: &str,
    published_at: &str,
) -> Result<()> {
    tx.execute(
        "UPDATE code_review_themes
         SET status = 'open',
             last_seen_head = COALESCE((
               SELECT observation.head_sha
               FROM code_review_theme_observations observation
               WHERE observation.theme_id = code_review_themes.id
                 AND observation.job_id = ?1 AND observation.published = 0
             ), last_seen_head),
             resolved_head = '',
             recurrence_count = recurrence_count + CASE WHEN EXISTS (
               SELECT 1 FROM code_review_theme_observations observation
               WHERE observation.theme_id = code_review_themes.id
                 AND observation.job_id = ?1 AND observation.published = 0
                 AND observation.kind = 'recurrence'
             ) THEN 1 ELSE 0 END,
             updated_at = ?2
         WHERE EXISTS (
           SELECT 1 FROM code_review_theme_observations observation
           WHERE observation.theme_id = code_review_themes.id
             AND observation.job_id = ?1 AND observation.published = 0
         )",
        params![job_id, published_at],
    )?;
    tx.execute(
        "UPDATE code_review_theme_observations SET published = 1
         WHERE job_id = ?1 AND published = 0",
        params![job_id],
    )?;
    Ok(())
}

fn resolve_code_review_themes_in_transaction(
    tx: &rusqlite::Transaction<'_>,
    repository: &str,
    pull_number: u64,
    resolved_head: &str,
    resolved_at: &str,
) -> Result<u64> {
    Ok(tx.execute(
        "UPDATE code_review_themes
         SET status = 'resolved', resolved_head = ?3, updated_at = ?4
         WHERE repository = ?1 AND pull_number = ?2 AND status = 'open'
           AND EXISTS (
             SELECT 1 FROM code_review_theme_observations observation
             WHERE observation.theme_id = code_review_themes.id
               AND observation.published != 0
           )
           AND NOT EXISTS (
             SELECT 1
             FROM code_review_finding_themes ft
             JOIN code_review_findings f ON f.id = ft.finding_id
             JOIN code_review_jobs j ON j.id = f.job_id
             LEFT JOIN code_review_jobs link_job ON link_job.id = ft.linked_by_job_id
             WHERE ft.theme_id = code_review_themes.id
               AND f.status = 'open' AND j.review_published != 0
               AND (ft.linked_by_job_id = '' OR link_job.review_published != 0)
           )",
        params![repository, pull_number as i64, resolved_head, resolved_at],
    )? as u64)
}

fn finalize_code_review_theme_publication(
    tx: &rusqlite::Transaction<'_>,
    job_id: &str,
    repository: &str,
    pull_number: u64,
    head_sha: &str,
    published_at: &str,
) -> Result<()> {
    publish_code_review_theme_observations(tx, job_id, published_at)?;
    resolve_code_review_themes_in_transaction(tx, repository, pull_number, head_sha, published_at)?;
    record_code_review_theme_transition_snapshots(tx, job_id, published_at, false)?;
    apply_code_review_theme_transition_snapshots(tx, job_id, false)?;
    Ok(())
}

/// Blocking findings gate the check; advisory findings (low severity, or
/// medium with low confidence, or a scope verdict this change could not be
/// tied to) are tracked separately as durable debt.
fn record_code_review_open_issue_count(tx: &rusqlite::Transaction<'_>, job_id: &str) -> Result<()> {
    tx.execute(
        &format!(
            "UPDATE code_review_jobs
         SET publication_open_issue_count = (
           SELECT COUNT(*)
           FROM code_review_findings finding
           JOIN code_review_jobs finding_job ON finding_job.id = finding.job_id
           WHERE finding_job.repository = code_review_jobs.repository
             AND finding_job.pull_number = code_review_jobs.pull_number
             AND finding_job.review_published != 0
             AND finding.status = 'open'
             AND {blocking}
         ),
         publication_advisory_open_issue_count = (
           SELECT COUNT(*)
           FROM code_review_findings finding
           JOIN code_review_jobs finding_job ON finding_job.id = finding.job_id
           WHERE finding_job.repository = code_review_jobs.repository
             AND finding_job.pull_number = code_review_jobs.pull_number
             AND finding_job.review_published != 0
             AND finding.status = 'open'
             AND NOT ({blocking})
         )
         WHERE id = ?1",
            blocking = blocking_finding_predicate("finding")
        ),
        params![job_id],
    )?;
    Ok(())
}

/// Shared body of the post-hoc count refresh: recompute both tier snapshots
/// on the newest published round, arm the blocking-review cleanup when the
/// blocking ledger reaches zero, disarm it (invalidating any in-flight
/// claim) when a reopen makes it positive again. Returns the round's id when
/// either tier changed and its GitHub projections should re-sync.
fn refresh_code_review_pull_projection_counts_in_tx(
    tx: &rusqlite::Transaction<'_>,
    repository: &str,
    pull_number: u64,
) -> Result<Option<String>> {
    let latest: Option<(String, Option<i64>, Option<i64>)> = tx
        .query_row(
            "SELECT id, publication_open_issue_count,
                    publication_advisory_open_issue_count
             FROM code_review_jobs
             WHERE repository = ?1 AND pull_number = ?2 AND review_published = 1
             ORDER BY publication_order DESC, created_at DESC, id DESC
             LIMIT 1",
            params![repository, pull_number as i64],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    let Some((job_id, previous_open, previous_advisory)) = latest else {
        return Ok(None);
    };
    record_code_review_open_issue_count(tx, &job_id)?;
    let (refreshed_open, refreshed_advisory): (Option<i64>, Option<i64>) = tx.query_row(
        "SELECT publication_open_issue_count, publication_advisory_open_issue_count
         FROM code_review_jobs WHERE id = ?1",
        params![job_id],
        |row| Ok((row.get(0)?, row.get(1)?)),
    )?;
    if refreshed_open == Some(0) && previous_open != Some(0) {
        // The gate cleared without a round (trusted dismissals): the
        // standing REQUEST_CHANGES review must not outlive the ledger.
        // The durable cleanup task dismisses it with retries.
        tx.execute(
            "UPDATE code_review_jobs
             SET blocking_review_cleanup_pending = 1,
                 blocking_review_cleanup_page = 1,
                 blocking_review_cleanup_attempts = 0,
                 blocking_review_cleanup_next_attempt_at = NULL,
                 blocking_review_cleanup_claim_token = NULL,
                 blocking_review_cleanup_claim_until = NULL
             WHERE id = ?1",
            params![job_id],
        )?;
    } else if refreshed_open.is_some_and(|open| open > 0) {
        // The ledger has open blocking findings again (a reopen): any
        // cleanup armed while it was clear must not proceed to dismiss
        // the standing REQUEST_CHANGES review out from under them.
        // Clearing the claim fields also invalidates an in-flight claim.
        tx.execute(
            "UPDATE code_review_jobs
             SET blocking_review_cleanup_pending = 0,
                 blocking_review_cleanup_claim_token = NULL,
                 blocking_review_cleanup_claim_until = NULL
             WHERE id = ?1 AND blocking_review_cleanup_pending != 0",
            params![job_id],
        )?;
    }
    // Either tier changing requires a fresh GitHub projection: advisory
    // counts surface in the check summary and lifecycle comment even
    // though only the blocking tier gates.
    Ok(
        (refreshed_open != previous_open || refreshed_advisory != previous_advisory)
            .then_some(job_id),
    )
}

fn parse_optional_datetime(value: Option<String>) -> Option<chrono::DateTime<chrono::Utc>> {
    value.and_then(|value| value.parse().ok())
}

fn code_review_scope_from(value: &str) -> trouve_protocol::CodeReviewJobScope {
    match value {
        "full" => trouve_protocol::CodeReviewJobScope::Full,
        _ => trouve_protocol::CodeReviewJobScope::Incremental,
    }
}

fn code_review_scope_str(value: trouve_protocol::CodeReviewJobScope) -> &'static str {
    match value {
        trouve_protocol::CodeReviewJobScope::Incremental => "incremental",
        trouve_protocol::CodeReviewJobScope::Full => "full",
    }
}

fn elapsed_ms(
    started: chrono::DateTime<chrono::Utc>,
    finished: chrono::DateTime<chrono::Utc>,
) -> u64 {
    finished
        .signed_duration_since(started)
        .num_milliseconds()
        .max(0) as u64
}

fn finalize_code_review_model_elapsed(
    recorded_model_elapsed_ms: i64,
    model_started_at: Option<String>,
    last_progress_at: Option<String>,
    finished: chrono::DateTime<chrono::Utc>,
) -> u64 {
    let recorded = recorded_model_elapsed_ms.max(0) as u64;
    let Some(started) = parse_optional_datetime(model_started_at) else {
        return recorded;
    };
    let progress_anchor = parse_optional_datetime(last_progress_at)
        .filter(|progress| *progress >= started)
        .unwrap_or(started);
    recorded.saturating_add(elapsed_ms(progress_anchor, finished))
}

fn job_elapsed_ms(
    status: &str,
    created_at: chrono::DateTime<chrono::Utc>,
    started_at: Option<chrono::DateTime<chrono::Utc>>,
    completed_at: Option<chrono::DateTime<chrono::Utc>>,
) -> (u64, u64) {
    let now = chrono::Utc::now();
    let pending_end = started_at.or(completed_at).unwrap_or(now);
    let pending = elapsed_ms(created_at, pending_end);
    let running = started_at
        .map(|started| elapsed_ms(started, completed_at.unwrap_or(now)))
        .unwrap_or(0);
    if status == "queued" {
        (elapsed_ms(created_at, now), 0)
    } else {
        (pending, running)
    }
}

fn row_to_code_review_repository(
    r: &rusqlite::Row<'_>,
) -> rusqlite::Result<trouve_protocol::CodeReviewRepository> {
    let mode: String = r.get(3)?;
    Ok(trouve_protocol::CodeReviewRepository {
        repository: r.get(0)?,
        installation_id: r.get::<_, i64>(1)? as u64,
        private: r.get(2)?,
        mode: code_review_mode_from(&mode),
        model: r.get(4)?,
        prompt: r.get(5)?,
        reviewer_ids: serde_json::from_str::<Vec<String>>(&r.get::<_, String>(6)?)
            .unwrap_or_else(|_| crate::reviewers::default_reviewer_ids()),
        routing_mode: code_review_routing_mode_from(&r.get::<_, String>(7)?),
        semantic_routing: r.get(8)?,
        included_reviewer_ids: serde_json::from_str::<Vec<String>>(&r.get::<_, String>(9)?)
            .unwrap_or_default(),
        excluded_reviewer_ids: serde_json::from_str::<Vec<String>>(&r.get::<_, String>(10)?)
            .unwrap_or_default(),
        reviewer_overrides: serde_json::from_str::<Vec<trouve_protocol::ReviewerOverride>>(
            &r.get::<_, String>(11)?,
        )
        .unwrap_or_default(),
        router_model: r.get(12)?,
        router_thinking_level: r.get(13)?,
        coordinator_thinking_level: r.get(14)?,
        analyst_model: r.get(15)?,
        analyst_thinking_level: r.get(16)?,
    })
}

