fn row_to_code_review_job(r: &rusqlite::Row<'_>) -> rusqlite::Result<CodeReviewJobRecord> {
    let reviewers: Vec<trouve_protocol::ReviewerProfile> =
        serde_json::from_str(&r.get::<_, String>(13)?).unwrap_or_default();
    let created_at = parse_datetime(r.get(19)?);
    let started_at = parse_optional_datetime(r.get(20)?);
    let completed_at = parse_optional_datetime(r.get(21)?);
    let status: String = r.get(10)?;
    let completed_reviewers = r.get::<_, i64>(31)? as u64;
    let total_reviewers = r.get::<_, i64>(32)? as u64;
    let percent = completed_reviewers
        .saturating_mul(100)
        .checked_div(total_reviewers)
        .map(|value| value.min(100) as u8)
        .unwrap_or_else(|| {
            u8::from(matches!(
                status.as_str(),
                "succeeded" | "failed" | "cancelled" | "stale"
            )) * 100
        });
    let (pending_elapsed_ms, running_elapsed_ms) =
        job_elapsed_ms(&status, created_at, started_at, completed_at);
    let base_ref: String = r.get(7)?;
    let review_base_sha: String = r.get(22)?;
    let review_watermark_sha: String = r.get(50)?;
    let effective_review_base_sha = if review_base_sha.is_empty() {
        base_ref.clone()
    } else {
        review_base_sha
    };
    Ok(CodeReviewJobRecord {
        job: trouve_protocol::CodeReviewJob {
            id: r.get(0)?,
            installation_id: r.get::<_, i64>(1)? as u64,
            repository: r.get(2)?,
            pull_number: r.get::<_, i64>(3)? as u64,
            pull_title: r.get(4)?,
            pull_url: r.get(5)?,
            head_sha: r.get(6)?,
            review_base_sha: effective_review_base_sha.clone(),
            review_watermark_sha: if review_watermark_sha.is_empty() {
                effective_review_base_sha
            } else {
                review_watermark_sha
            },
            covered_full_branch: r.get(62)?,
            base_ref,
            head_ref: r.get(8)?,
            scope: code_review_scope_from(&r.get::<_, String>(23)?),
            trigger: r.get(9)?,
            status,
            retry_of: r.get(24)?,
            retried_by: r.get(25)?,
            model: r.get(11)?,
            coordinator_thinking_level: r.get(49)?,
            router_model: r.get(47)?,
            router_thinking_level: r.get(48)?,
            analyst_model: r.get(58)?,
            analyst_thinking_level: r.get(59)?,
            reviewer_ids: reviewers
                .iter()
                .map(|reviewer| reviewer.id.clone())
                .collect(),
            routing_mode: code_review_routing_mode_from(&r.get::<_, String>(43)?),
            semantic_routing: r.get(44)?,
            included_reviewer_ids: serde_json::from_str::<Vec<String>>(&r.get::<_, String>(45)?)
                .unwrap_or_default(),
            excluded_reviewer_ids: serde_json::from_str::<Vec<String>>(&r.get::<_, String>(46)?)
                .unwrap_or_default(),
            session_id: r.get(15)?,
            thread_id: r.get(16)?,
            review_url: r.get(17)?,
            lifecycle_comment_url: r.get(26)?,
            check_run_id: r.get::<_, Option<i64>>(27)?.map(|value| value as u64),
            check_run_url: r.get(28)?,
            check_sync_error: r.get(29)?,
            cancel_requested: r.get(30)?,
            progress: trouve_protocol::CodeReviewProgress {
                completed_reviewers,
                total_reviewers,
                percent,
            },
            candidate_issue_count: r.get::<_, i64>(33)? as u64,
            issue_count: r.get::<_, i64>(34)? as u64,
            fixed_issue_count: r.get::<_, i64>(35)? as u64,
            open_issue_count: r
                .get::<_, Option<i64>>(56)?
                .map(|value| value.max(0) as u64),
            advisory_open_issue_count: r
                .get::<_, Option<i64>>(60)?
                .map(|value| value.max(0) as u64),
            error: r.get(18)?,
            created_at,
            started_at,
            completed_at,
            pending_elapsed_ms,
            running_elapsed_ms,
            preparation_elapsed_ms: r.get::<_, i64>(39)? as u64,
            reviewer_elapsed_ms: r.get::<_, i64>(40)? as u64,
            coordinator_elapsed_ms: r.get::<_, i64>(41)? as u64,
            publication_elapsed_ms: r.get::<_, i64>(42)? as u64,
        },
        can_retry_final_editor: r.get(61)?,
        prompt: r.get(12)?,
        pull_body: r.get(57)?,
        config_hash: r.get(14)?,
        reviewers,
        summary: r.get(36)?,
        prompt_for_agents: r.get(37)?,
        publication_claimed: r.get(38)?,
        publication_accepted: r.get(52)?,
        review_published: r.get(53)?,
        blocking_review_cleanup_pending: r.get(54)?,
        publication_dispatched: r.get(55)?,
    })
}

const CODE_REVIEW_JOB_COLUMNS: &str = "id, installation_id, repository, pull_number, pull_title, pull_url, head_sha, \
     base_ref, head_ref, trigger, status, model, prompt, identities, config_hash, session_id, thread_id, \
     review_url, error, created_at, started_at, completed_at, review_base_sha, review_scope, retry_of, \
     retried_by, lifecycle_comment_url, check_run_id, check_run_url, check_sync_error, cancel_requested, \
     completed_reviewers, total_reviewers, candidate_issue_count, issue_count, fixed_issue_count, summary, \
     prompt_for_agents, publication_claimed, preparation_elapsed_ms, reviewer_elapsed_ms, \
     coordinator_elapsed_ms, publication_elapsed_ms, routing_mode, semantic_routing, \
     included_reviewer_ids, excluded_reviewer_ids, router_model, router_thinking_level, \
     coordinator_thinking_level, review_watermark_sha, review_batch_digest, publication_accepted, \
     review_published, blocking_review_cleanup_pending, publication_dispatched, \
     publication_open_issue_count, pull_body, \
     analyst_model, analyst_thinking_level, publication_advisory_open_issue_count, \
     CASE WHEN code_review_jobs.status IN ('failed', 'cancelled') \
            AND code_review_jobs.session_id IS NULL \
            AND EXISTS ( \
              SELECT 1 FROM code_review_tasks AS coordinator \
              WHERE coordinator.job_id = code_review_jobs.id \
                AND coordinator.role = 'coordinator' \
                AND coordinator.status IN ('failed', 'cancelled') \
                AND NOT EXISTS ( \
                  SELECT 1 FROM code_review_tasks AS newer_coordinator \
                  WHERE newer_coordinator.job_id = coordinator.job_id \
                    AND newer_coordinator.role = 'coordinator' \
                    AND newer_coordinator.rowid > coordinator.rowid \
                ) \
            ) \
            AND NOT EXISTS ( \
              SELECT 1 FROM code_review_tasks AS reviewer \
              WHERE reviewer.job_id = code_review_jobs.id \
                AND reviewer.role = 'reviewer' \
                AND reviewer.reviewer_id IS NOT NULL \
                AND reviewer.status NOT IN ('succeeded', 'not_applicable', 'superseded') \
                AND NOT EXISTS ( \
                  SELECT 1 FROM code_review_tasks AS newer_reviewer \
                  WHERE newer_reviewer.job_id = reviewer.job_id \
                    AND newer_reviewer.role = 'reviewer' \
                    AND newer_reviewer.reviewer_id = reviewer.reviewer_id \
                    AND newer_reviewer.batch_index = reviewer.batch_index \
                    AND newer_reviewer.rowid > reviewer.rowid \
                ) \
            ) \
          THEN 1 ELSE 0 END AS can_retry_final_editor, \
     review_covered_full_branch";

/// Shared ownership predicate for accepting review results and claiming their
/// publication. Keeping both transitions on one predicate prevents stale
/// workers from persisting after cancellation or same-generation replacement.
const CURRENT_CODE_REVIEW_JOB_PREDICATE: &str = concat!(
    "code_review_jobs.id = ?1 ",
    "AND code_review_jobs.status = 'running' ",
    "AND code_review_jobs.cancel_requested = 0 ",
    "AND code_review_jobs.publication_claimed = 0 ",
    "AND NOT EXISTS (",
    "  SELECT 1 FROM code_review_jobs AS newer ",
    "  WHERE newer.repository = code_review_jobs.repository ",
    "    AND newer.pull_number = code_review_jobs.pull_number ",
    "    AND newer.head_sha = code_review_jobs.head_sha ",
    "    AND (",
    "      newer.publication_generation > code_review_jobs.publication_generation ",
    "      OR (",
    "        newer.publication_generation = code_review_jobs.publication_generation ",
    "        AND newer.rowid > code_review_jobs.rowid",
    "      )",
    "    ) ",
    "    AND newer.status IN ('queued', 'running', 'succeeded')",
    ")",
);

