fn latest_code_review_task_attempts(
    attempts: &[CodeReviewTaskAttempt],
) -> Vec<&CodeReviewTaskAttempt> {
    let mut latest = BTreeMap::new();
    for attempt in attempts {
        let task = &attempt.task;
        if task.role != trouve_protocol::CodeReviewTaskRole::Reviewer {
            continue;
        }
        let Some(reviewer_id) = task.reviewer_id.as_ref() else {
            continue;
        };
        let key = (reviewer_id.clone(), task.batch_index);
        let replace = latest
            .get(&key)
            .is_none_or(|current: &&CodeReviewTaskAttempt| {
                attempt.insertion_order > current.insertion_order
            });
        if replace {
            latest.insert(key, attempt);
        }
    }
    latest
        .into_values()
        .filter(|attempt| attempt.task.status != "superseded")
        .collect()
}

fn completed_code_review_persona_count(attempts: &[CodeReviewTaskAttempt]) -> u64 {
    let mut grouped: BTreeMap<String, Vec<&trouve_protocol::CodeReviewTask>> = BTreeMap::new();
    for attempt in latest_code_review_task_attempts(attempts) {
        let task = &attempt.task;
        if let Some(reviewer_id) = task.reviewer_id.as_ref() {
            grouped.entry(reviewer_id.clone()).or_default().push(task);
        }
    }
    grouped
        .into_values()
        .filter(|tasks| {
            tasks.iter().all(|task| {
                matches!(
                    task.status.as_str(),
                    "succeeded" | "failed" | "cancelled" | "not_applicable"
                )
            }) && tasks.len() as u64 >= tasks.iter().map(|task| task.batch_count).max().unwrap_or(0)
        })
        .count() as u64
}

fn enqueue_code_review_pending_event(
    tx: &rusqlite::Transaction<'_>,
    job_id: &str,
    event: &Event,
) -> Result<()> {
    tx.execute(
        "INSERT INTO code_review_pending_events (job_id, payload, created_at)
         VALUES (?1, ?2, ?3)",
        params![
            job_id,
            serde_json::to_string(event)?,
            chrono::Utc::now().to_rfc3339()
        ],
    )?;
    Ok(())
}

fn supersede_code_review_task(
    tx: &rusqlite::Transaction<'_>,
    task_id: &str,
    job_id: &str,
    completed_at: &str,
    recovery_message: &str,
) -> Result<bool> {
    let updated = tx.execute(
        "UPDATE code_review_tasks
         SET status = 'superseded',
             completed_at = COALESCE(completed_at, ?3),
             error = CASE
               WHEN status IN ('succeeded', 'failed', 'cancelled', 'not_applicable')
                 THEN error
               ELSE ?4
             END
         WHERE id = ?1 AND job_id = ?2 AND status != 'superseded'",
        params![task_id, job_id, completed_at, recovery_message],
    )?;
    if updated == 0 {
        return Ok(false);
    }
    let task = tx.query_row(
        &format!("SELECT {CODE_REVIEW_TASK_COLUMNS} FROM code_review_tasks WHERE id = ?1"),
        [task_id],
        row_to_code_review_task,
    )?;
    enqueue_code_review_pending_event(
        tx,
        job_id,
        &Event::CodeReviewTaskUpdated {
            job_id: job_id.to_owned(),
            task: Box::new(task),
        },
    )?;
    Ok(true)
}

fn cancel_active_code_review_tasks(
    tx: &Transaction<'_>,
    job_id: &str,
    reviewer_id: Option<&str>,
    completed_at: &str,
    error: &str,
) -> Result<Vec<trouve_protocol::CodeReviewTask>> {
    let task_ids = {
        let mut stmt = tx.prepare(
            "SELECT id FROM code_review_tasks
             WHERE job_id = ?1 AND status IN ('queued', 'running')
               AND (?2 IS NULL OR reviewer_id = ?2)
             ORDER BY rowid",
        )?;
        let rows = stmt.query_map(params![job_id, reviewer_id], |row| row.get::<_, String>(0))?;
        rows.collect::<rusqlite::Result<Vec<_>>>()?
    };
    if task_ids.is_empty() {
        return Ok(Vec::new());
    }
    tx.execute(
        "UPDATE code_review_tasks
         SET status = 'cancelled', completed_at = ?2, error = ?3,
             model_elapsed_ms = CASE
               WHEN status != 'running' OR model_started_at IS NULL THEN model_elapsed_ms
               ELSE model_elapsed_ms + MAX(
                 0,
                 CAST(
                   (julianday(?2) - MAX(
                     julianday(model_started_at),
                     julianday(COALESCE(last_progress_at, model_started_at))
                   )) * 86400000 AS INTEGER
                 )
               )
             END
         WHERE job_id = ?1 AND status IN ('queued', 'running')
           AND (?4 IS NULL OR reviewer_id = ?4)",
        params![job_id, completed_at, error, reviewer_id],
    )?;
    task_ids
        .into_iter()
        .map(|task_id| {
            tx.query_row(
                &format!("SELECT {CODE_REVIEW_TASK_COLUMNS} FROM code_review_tasks WHERE id = ?1"),
                params![task_id],
                row_to_code_review_task,
            )
            .map_err(Into::into)
        })
        .collect()
}

/// A durable threadless resolve/unresolve command claimed from a webhook
/// delivery, retried until it reaches a definitive outcome.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PendingThreadlessCommand {
    pub trigger_key: String,
    pub repository: String,
    pub pull_number: u64,
    pub comment_id: u64,
    pub author: String,
    pub resolve: bool,
    pub finding_prefix: String,
    pub reason: String,
    /// Claim time, set by the store when the delivery is claimed. Used to
    /// bound how long a premature no-op is retained for replay.
    pub created_at: String,
}

/// Outcome of a maintainer resolve/unresolve command against the threadless
/// finding ledger.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ThreadlessCommandOutcome {
    Applied {
        finding_id: String,
    },
    AmbiguousPrefix {
        matches: usize,
    },
    NotFound,
    /// The prefix matched exactly one finding, but it is not in the state
    /// the verb expects (already resolved, or not resolved).
    NotApplicable {
        finding_id: String,
        status: String,
    },
    /// Another processor consumed this command's durable row first; nothing
    /// was evaluated or mutated.
    AlreadyConsumed,
    /// The command is not applicable yet, but an out-of-order sibling
    /// delivery could still make it applicable, so its row was retained for
    /// replay instead of being consumed.
    NotApplicableDeferred,
}

