pub struct Store {
    conn: Arc<Mutex<Connection>>,
    events_tx: broadcast::Sender<EventEnvelope>,
    scoped_events: ScopedEventSenders,
    append_tx: std::sync::mpsc::Sender<AppendRequest>,
}

