    #[test]
    fn migration_marks_pre_authority_observations_consumed_without_replay() {
        let data = tempfile::tempdir().unwrap();
        let database = data.path().join("legacy-theme-observation.sqlite3");
        let store = Store::open(&database).unwrap();
        let job = enqueue_backoff_test_job(&store);
        let findings = store
            .save_code_review_result_with_themes(
                &job.id,
                "summary",
                "fix the root cause",
                1,
                &[NewCodeReviewFinding {
                    path: "src/lib.rs".into(),
                    line: 3,
                    side: "RIGHT".into(),
                    severity: "high".into(),
                    confidence: "high".into(),
                    title: "Legacy symptom".into(),
                    body: "The invariant is broken.".into(),
                    prompt_for_agents: "Restore it.".into(),
                    sources: Vec::new(),
                }],
                &[NewCodeReviewFindingDetails {
                    theme_ids: vec!["legacy-theme".into()],
                    ..Default::default()
                }],
                &[NewCodeReviewTheme {
                    id: "legacy-theme".into(),
                    root_cause: "legacy root cause".into(),
                    recommendation: "preserve legacy authority".into(),
                    observation_kind: trouve_protocol::CodeReviewThemeObservationKind::New,
                    previous_finding_ids: Vec::new(),
                }],
                &[],
            )
            .unwrap();
        {
            let conn = store.conn.lock().unwrap();
            conn.execute(
                "UPDATE code_review_jobs
                 SET review_url = 'https://github.com/acme/widgets/pull/42#pullrequestreview-7',
                     review_published = 0, publication_accepted = 0
                 WHERE id = ?1",
                [&job.id],
            )
            .unwrap();
            conn.execute(
                "UPDATE code_review_theme_observations SET kind = 'recurrence'
                 WHERE job_id = ?1",
                [&job.id],
            )
            .unwrap();
            conn.execute(
                "UPDATE code_review_themes
                 SET status = 'resolved', last_seen_head = 'legacy-applied-head',
                     resolved_head = 'legacy-resolved-head', recurrence_count = 7
                 WHERE id = 'acme/widgets#42:legacy-theme'",
                [],
            )
            .unwrap();
            conn.execute(
                "UPDATE code_review_findings
                 SET status = 'fixed', resolved_at = '2000-01-01T00:00:00Z',
                     resolved_head = 'legacy-resolved-head',
                     resolved_by_job_id = ''
                 WHERE id = ?1",
                [&findings[0].id],
            )
            .unwrap();
            conn.execute(
                "INSERT OR REPLACE INTO code_review_theme_transitions
                   (theme_id, job_id, status, last_seen_head, resolved_head,
                    recurrence_count, transitioned_at, writer_version)
                 VALUES ('acme/widgets#42:legacy-theme', ?1, 'open',
                         'transition-only-head', '', 1,
                         '2000-01-01T00:00:00Z', 1)",
                [&job.id],
            )
            .unwrap();
        }
        drop(store);

        // Recreate the pre-publication-authority table shape, then simulate an
        // interrupted migration that already added writer_version and
        // committed its zero defaults but stopped before classifying them.
        let legacy = Connection::open(&database).unwrap();
        legacy
            .execute_batch(
                "ALTER TABLE code_review_theme_observations RENAME TO legacy_theme_observations;
                 CREATE TABLE code_review_theme_observations (
                   theme_id TEXT NOT NULL REFERENCES code_review_themes(id),
                   job_id TEXT NOT NULL REFERENCES code_review_jobs(id),
                   head_sha TEXT NOT NULL,
                   kind TEXT NOT NULL,
                   created_at TEXT NOT NULL,
                   PRIMARY KEY (theme_id, job_id)
                 );
                 INSERT INTO code_review_theme_observations
                   (theme_id, job_id, head_sha, kind, created_at)
                 SELECT theme_id, job_id, head_sha, kind, created_at
                 FROM legacy_theme_observations;
                 DROP TABLE legacy_theme_observations;
                 ALTER TABLE code_review_theme_transitions
                   RENAME TO legacy_theme_transitions;
                 CREATE TABLE code_review_theme_transitions (
                   theme_id TEXT NOT NULL REFERENCES code_review_themes(id),
                   job_id TEXT NOT NULL REFERENCES code_review_jobs(id),
                   status TEXT NOT NULL,
                   last_seen_head TEXT NOT NULL,
                   resolved_head TEXT NOT NULL DEFAULT '',
                   recurrence_count INTEGER NOT NULL DEFAULT 0,
                   transitioned_at TEXT NOT NULL,
                   writer_version INTEGER NOT NULL DEFAULT 0,
                   PRIMARY KEY (theme_id, job_id)
                 );
                 INSERT INTO code_review_theme_transitions
                   (theme_id, job_id, status, last_seen_head, resolved_head,
                    recurrence_count, transitioned_at, writer_version)
                 SELECT theme_id, job_id, status, last_seen_head, resolved_head,
                        recurrence_count, transitioned_at, 0
                 FROM legacy_theme_transitions;
                 DROP TABLE legacy_theme_transitions;
                 DELETE FROM store_migrations
                 WHERE id = 'code-review-theme-observation-publication-authority-v1';",
            )
            .unwrap();
        drop(legacy);

        let reopened = Store::open(&database).unwrap();
        assert!(
            reopened
                .code_review_job(&job.id)
                .unwrap()
                .unwrap()
                .review_published
        );
        let published = reopened
            .conn
            .lock()
            .unwrap()
            .query_row(
                "SELECT published FROM code_review_theme_observations WHERE job_id = ?1",
                [&job.id],
                |row| row.get::<_, bool>(0),
            )
            .unwrap();
        assert!(published);
        let preserved_writer_version = reopened
            .conn
            .lock()
            .unwrap()
            .query_row(
                "SELECT writer_version
                 FROM code_review_theme_transitions
                 WHERE theme_id = 'acme/widgets#42:legacy-theme'",
                [],
                |row| row.get::<_, i64>(0),
            )
            .unwrap();
        assert_eq!(preserved_writer_version, -1);
        let themes = reopened.code_review_themes_for_job(&job.id).unwrap();
        assert_eq!(themes.len(), 1);
        assert_eq!(themes[0].status, "resolved");
        assert_eq!(themes[0].last_seen_head, "legacy-applied-head");
        assert_eq!(themes[0].resolved_head, "legacy-resolved-head");
        assert_eq!(themes[0].recurrence_count, 7);
        let migration_recorded = reopened
            .conn
            .lock()
            .unwrap()
            .query_row(
                "SELECT EXISTS (
                   SELECT 1 FROM store_migrations
                   WHERE id = 'code-review-theme-observation-publication-authority-v1'
                 )",
                [],
                |row| row.get::<_, bool>(0),
            )
            .unwrap();
        assert!(migration_recorded);
    }

    #[test]
    fn migration_rebuilds_all_staged_observations() {
        let data = tempfile::tempdir().unwrap();
        let database = data
            .path()
            .join("authority-aware-theme-observation.sqlite3");
        let store = Store::open(&database).unwrap();
        let job = enqueue_backoff_test_job(&store);
        let findings = store
            .save_code_review_result_with_themes(
                &job.id,
                "summary",
                "fix the root cause",
                1,
                &[NewCodeReviewFinding {
                    path: "src/lib.rs".into(),
                    line: 3,
                    side: "RIGHT".into(),
                    severity: "high".into(),
                    confidence: "high".into(),
                    title: "Staged symptom".into(),
                    body: "The staged transition must survive schema upgrade.".into(),
                    prompt_for_agents: "Preserve publication authority.".into(),
                    sources: Vec::new(),
                }],
                &[NewCodeReviewFindingDetails {
                    theme_ids: vec!["staged-theme".into()],
                    ..Default::default()
                }],
                &[NewCodeReviewTheme {
                    id: "staged-theme".into(),
                    root_cause: "staged root cause".into(),
                    recommendation: "promote after publication repair".into(),
                    observation_kind: trouve_protocol::CodeReviewThemeObservationKind::New,
                    previous_finding_ids: Vec::new(),
                }],
                &[],
            )
            .unwrap();
        let theme_id = findings[0].theme_ids[0].clone();
        let mut second_request = backoff_test_job_request();
        second_request.dedupe_key = "acme/widgets#42:second-staged".into();
        second_request.head_sha = "3333333333333333333333333333333333333333".into();
        let second_job = store
            .enqueue_code_review_job(&second_request)
            .unwrap()
            .unwrap();
        {
            let conn = store.conn.lock().unwrap();
            conn.execute(
                "UPDATE code_review_jobs
                 SET review_url = 'https://github.com/acme/widgets/pull/42#pullrequestreview-9',
                     review_published = 0, publication_accepted = 0,
                     publication_claimed = 1, publication_order = 1
                 WHERE id = ?1",
                [&job.id],
            )
            .unwrap();
            conn.execute(
                "UPDATE code_review_jobs
                 SET review_url = 'https://github.com/acme/widgets/pull/42#pullrequestreview-10',
                     review_published = 0, publication_accepted = 0,
                     publication_claimed = 1, publication_order = 2
                 WHERE id = ?1",
                [&second_job.id],
            )
            .unwrap();
            conn.execute(
                "INSERT INTO code_review_theme_observations
                   (theme_id, job_id, head_sha, kind, published,
                    publication_managed, created_at)
                 VALUES (?1, ?2, ?3, 'recurrence', 0, 1, ?4)",
                params![
                    theme_id,
                    second_job.id,
                    second_job.head_sha,
                    chrono::Utc::now().to_rfc3339()
                ],
            )
            .unwrap();
        }
        drop(store);

        // Recreate the immediately preceding authority-aware shape: staged
        // publication state exists, but per-row provenance does not yet.
        let legacy = Connection::open(&database).unwrap();
        legacy
            .execute_batch(
                "ALTER TABLE code_review_theme_observations RENAME TO authority_observations;
                 CREATE TABLE code_review_theme_observations (
                   theme_id TEXT NOT NULL REFERENCES code_review_themes(id),
                   job_id TEXT NOT NULL REFERENCES code_review_jobs(id),
                   head_sha TEXT NOT NULL,
                   kind TEXT NOT NULL,
                   published INTEGER NOT NULL DEFAULT 0,
                   created_at TEXT NOT NULL,
                   PRIMARY KEY (theme_id, job_id)
                 );
                 INSERT INTO code_review_theme_observations
                   (theme_id, job_id, head_sha, kind, published, created_at)
                 SELECT theme_id, job_id, head_sha, kind, published, created_at
                 FROM authority_observations;
                 DROP TABLE authority_observations;
                 DELETE FROM store_migrations
                 WHERE id = 'code-review-theme-transitions-v1';",
            )
            .unwrap();
        drop(legacy);

        let reopened = Store::open(&database).unwrap();
        let observation = reopened
            .conn
            .lock()
            .unwrap()
            .query_row(
                "SELECT published, publication_managed
                 FROM code_review_theme_observations WHERE job_id = ?1",
                [&job.id],
                |row| Ok((row.get::<_, bool>(0)?, row.get::<_, bool>(1)?)),
            )
            .unwrap();
        assert_eq!(observation, (true, true));
        let second_observation = reopened
            .conn
            .lock()
            .unwrap()
            .query_row(
                "SELECT published, publication_managed
                 FROM code_review_theme_observations WHERE job_id = ?1",
                [&second_job.id],
                |row| Ok((row.get::<_, bool>(0)?, row.get::<_, bool>(1)?)),
            )
            .unwrap();
        assert_eq!(second_observation, (true, true));
        let themes = reopened.code_review_themes_for_job(&job.id).unwrap();
        assert_eq!(themes[0].status, "open");
        assert_eq!(themes[0].last_seen_head, second_job.head_sha);
        assert_eq!(themes[0].recurrence_count, 1);
    }

    #[test]
    fn publication_records_final_theme_transition_snapshots() {
        let store = Store::open_in_memory().unwrap();
        let first_job = enqueue_backoff_test_job(&store);
        assert_eq!(
            store.claim_code_review_job().unwrap().unwrap().job.id,
            first_job.id
        );
        let findings = store
            .save_code_review_result_with_themes(
                &first_job.id,
                "one issue",
                "fix it",
                1,
                &[NewCodeReviewFinding {
                    path: "src/lib.rs".into(),
                    line: 3,
                    side: "RIGHT".into(),
                    severity: "high".into(),
                    confidence: "high".into(),
                    title: "Published issue".into(),
                    body: "The first transition stays open.".into(),
                    prompt_for_agents: "Fix it.".into(),
                    sources: Vec::new(),
                }],
                &[NewCodeReviewFindingDetails {
                    theme_ids: vec!["transition-theme".into()],
                    ..Default::default()
                }],
                &[NewCodeReviewTheme {
                    id: "transition-theme".into(),
                    root_cause: "transition root cause".into(),
                    recommendation: "persist final publication state".into(),
                    observation_kind: trouve_protocol::CodeReviewThemeObservationKind::New,
                    previous_finding_ids: Vec::new(),
                }],
                &[],
            )
            .unwrap();
        assert!(store.claim_code_review_publication(&first_job.id).unwrap());
        store
            .record_code_review_publication(
                &first_job.id,
                &first_job.repository,
                first_job.pull_number,
                &first_job.base_ref,
                &first_job.head_sha,
                "https://example.test/review/transition-1",
                false,
                &[],
            )
            .unwrap();
        let theme_id = findings[0].theme_ids[0].clone();
        let first_transition = store
            .conn
            .lock()
            .unwrap()
            .query_row(
                "SELECT status, resolved_head
                 FROM code_review_theme_transitions
                 WHERE theme_id = ?1 AND job_id = ?2",
                params![theme_id, first_job.id],
                |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
            )
            .unwrap();
        assert_eq!(first_transition, ("open".into(), String::new()));

        store
            .finish_code_review_job(
                &first_job.id,
                "succeeded",
                "https://example.test/review/transition-1",
                "",
            )
            .unwrap();
        let mut second_request = backoff_test_job_request();
        second_request.dedupe_key = "acme/widgets#42:transition-2".into();
        second_request.head_sha = "3333333333333333333333333333333333333333".into();
        let second_job = store
            .enqueue_code_review_job(&second_request)
            .unwrap()
            .unwrap();
        assert_eq!(
            store.claim_code_review_job().unwrap().unwrap().job.id,
            second_job.id
        );
        store
            .save_code_review_result(&second_job.id, "clean", "", 0, &[], &[])
            .unwrap();
        assert!(store.claim_code_review_publication(&second_job.id).unwrap());
        store
            .record_code_review_publication(
                &second_job.id,
                &second_job.repository,
                second_job.pull_number,
                &second_job.base_ref,
                &second_job.head_sha,
                "https://example.test/review/transition-2",
                false,
                &[&findings[0].id],
            )
            .unwrap();
        let second_transition = store
            .conn
            .lock()
            .unwrap()
            .query_row(
                "SELECT status, resolved_head, last_seen_head
                 FROM code_review_theme_transitions
                 WHERE theme_id = ?1 AND job_id = ?2",
                params![theme_id, second_job.id],
                |row| {
                    Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, String>(1)?,
                        row.get::<_, String>(2)?,
                    ))
                },
            )
            .unwrap();
        assert_eq!(
            second_transition,
            ("resolved".into(), second_job.head_sha, first_job.head_sha)
        );
    }

    #[test]
    fn startup_repair_preserves_legacy_closure_timing() {
        let data = tempfile::tempdir().unwrap();
        let database = data.path().join("legacy-theme-transition-v2.sqlite3");
        let store = Store::open(&database).unwrap();
        let first_job = enqueue_backoff_test_job(&store);
        assert_eq!(
            store.claim_code_review_job().unwrap().unwrap().job.id,
            first_job.id
        );
        let finding = store
            .save_code_review_result_with_themes(
                &first_job.id,
                "one issue",
                "fix it",
                1,
                &[NewCodeReviewFinding {
                    path: "src/lib.rs".into(),
                    line: 3,
                    side: "RIGHT".into(),
                    severity: "high".into(),
                    confidence: "high".into(),
                    title: "Legacy issue".into(),
                    body: "The closure must not apply to the earlier snapshot.".into(),
                    prompt_for_agents: "Fix it.".into(),
                    sources: Vec::new(),
                }],
                &[NewCodeReviewFindingDetails {
                    theme_ids: vec!["legacy-transition-theme".into()],
                    ..Default::default()
                }],
                &[NewCodeReviewTheme {
                    id: "legacy-transition-theme".into(),
                    root_cause: "legacy transition root cause".into(),
                    recommendation: "retain temporal ordering".into(),
                    observation_kind: trouve_protocol::CodeReviewThemeObservationKind::New,
                    previous_finding_ids: Vec::new(),
                }],
                &[],
            )
            .unwrap()
            .remove(0);
        assert!(store.claim_code_review_publication(&first_job.id).unwrap());
        store
            .record_code_review_publication(
                &first_job.id,
                &first_job.repository,
                first_job.pull_number,
                &first_job.base_ref,
                &first_job.head_sha,
                "https://example.test/review/legacy-transition-1",
                false,
                &[],
            )
            .unwrap();
        store
            .finish_code_review_job(
                &first_job.id,
                "succeeded",
                "https://example.test/review/legacy-transition-1",
                "",
            )
            .unwrap();

        let mut second_request = backoff_test_job_request();
        second_request.dedupe_key = "acme/widgets#42:legacy-transition-2".into();
        second_request.head_sha = "3333333333333333333333333333333333333333".into();
        let second_job = store
            .enqueue_code_review_job(&second_request)
            .unwrap()
            .unwrap();
        assert_eq!(
            store.claim_code_review_job().unwrap().unwrap().job.id,
            second_job.id
        );
        store
            .save_code_review_result(&second_job.id, "clean", "", 0, &[], &[])
            .unwrap();
        assert!(store.claim_code_review_publication(&second_job.id).unwrap());
        store
            .record_code_review_publication(
                &second_job.id,
                &second_job.repository,
                second_job.pull_number,
                &second_job.base_ref,
                &second_job.head_sha,
                "https://example.test/review/legacy-transition-2",
                false,
                &[&finding.id],
            )
            .unwrap();
        store
            .finish_code_review_job(
                &second_job.id,
                "succeeded",
                "https://example.test/review/legacy-transition-2",
                "",
            )
            .unwrap();
        let theme_id = finding.theme_ids[0].clone();
        {
            let conn = store.conn.lock().unwrap();
            conn.execute(
                "UPDATE code_review_findings
                 SET resolved_by_job_id = ''
                 WHERE id = ?1",
                [&finding.id],
            )
            .unwrap();
            conn.execute(
                "UPDATE code_review_theme_transitions
                 SET status = 'open', resolved_head = '', writer_version = 0
                 WHERE theme_id = ?1",
                [&theme_id],
            )
            .unwrap();
            let repair_marker_exists = conn
                .query_row(
                    "SELECT EXISTS (
                       SELECT 1 FROM store_migrations
                       WHERE id = 'code-review-theme-transitions-v2'
                     )",
                    [],
                    |row| row.get::<_, bool>(0),
                )
                .unwrap();
            assert!(repair_marker_exists);
            conn.execute(
                "INSERT OR REPLACE INTO code_review_theme_observations
                   (theme_id, job_id, head_sha, kind, published,
                    publication_managed, created_at)
                 VALUES (?1, ?2, ?3, 'recurrence', 1, 0,
                         '1999-01-01T00:00:00Z')",
                params![theme_id, second_job.id, second_job.head_sha],
            )
            .unwrap();
            conn.execute(
                "UPDATE code_review_jobs SET completed_at = NULL WHERE id = ?1",
                [&second_job.id],
            )
            .unwrap();
        }
        drop(store);

        let reopened = Store::open(&database).unwrap();
        let transitions = {
            let conn = reopened.conn.lock().unwrap();
            let mut stmt = conn
                .prepare(
                    "SELECT transition.status, transition.resolved_head,
                            transition.writer_version
                     FROM code_review_theme_transitions AS transition
                     JOIN code_review_jobs AS job ON job.id = transition.job_id
                     WHERE transition.theme_id = ?1
                     ORDER BY job.publication_order",
                )
                .unwrap();
            stmt.query_map([&theme_id], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, i64>(2)?,
                ))
            })
            .unwrap()
            .collect::<rusqlite::Result<Vec<_>>>()
            .unwrap()
        };
        assert_eq!(
            transitions,
            vec![
                ("open".into(), String::new(), 1),
                ("resolved".into(), second_job.head_sha.clone(), 1),
            ]
        );
        let theme = reopened
            .code_review_themes_for_job(&first_job.id)
            .unwrap()
            .remove(0);
        assert_eq!(theme.status, "resolved");
        assert_eq!(theme.resolved_head, second_job.head_sha);

        {
            let conn = reopened.conn.lock().unwrap();
            let tx = write_transaction(&conn).unwrap();
            tx.execute(
                "UPDATE code_review_findings
                 SET resolved_at = NULL, resolved_head = ''
                 WHERE id = ?1",
                [&finding.id],
            )
            .unwrap();
            tx.execute(
                "DELETE FROM code_review_theme_transitions WHERE theme_id = ?1",
                [&theme_id],
            )
            .unwrap();
            record_code_review_theme_transition_snapshots(&tx, &first_job.id, "", false).unwrap();
            tx.commit().unwrap();
        }
        let filtered_first_status = reopened
            .conn
            .lock()
            .unwrap()
            .query_row(
                "SELECT status
                 FROM code_review_theme_transitions
                 WHERE theme_id = ?1 AND job_id = ?2",
                params![theme_id, first_job.id],
                |row| row.get::<_, String>(0),
            )
            .unwrap();
        assert_eq!(filtered_first_status, "open");

        {
            let conn = reopened.conn.lock().unwrap();
            let tx = write_transaction(&conn).unwrap();
            tx.execute(
                "UPDATE code_review_findings
                 SET resolved_at = '2999-01-01T00:00:00Z',
                     resolved_head = ?2
                 WHERE id = ?1",
                params![finding.id, second_job.head_sha],
            )
            .unwrap();
            tx.execute(
                "DELETE FROM code_review_theme_transitions WHERE theme_id = ?1",
                [&theme_id],
            )
            .unwrap();
            record_code_review_theme_transition_snapshots(&tx, "", "", false).unwrap();
            tx.execute(
                "UPDATE code_review_theme_transitions
                 SET status = 'resolved', resolved_head = ?2, writer_version = 0
                 WHERE theme_id = ?1",
                params![theme_id, second_job.head_sha],
            )
            .unwrap();
            tx.commit().unwrap();
        }
        drop(reopened);

        let reopened = Store::open(&database).unwrap();
        let repaired_statuses = {
            let conn = reopened.conn.lock().unwrap();
            let mut stmt = conn
                .prepare(
                    "SELECT transition.status, transition.writer_version
                     FROM code_review_theme_transitions AS transition
                     JOIN code_review_jobs AS job ON job.id = transition.job_id
                     WHERE transition.theme_id = ?1
                     ORDER BY job.publication_order",
                )
                .unwrap();
            stmt.query_map([&theme_id], |row| {
                Ok((row.get::<_, String>(0)?, row.get::<_, i64>(1)?))
            })
            .unwrap()
            .collect::<rusqlite::Result<Vec<_>>>()
            .unwrap()
        };
        assert_eq!(
            repaired_statuses,
            vec![("open".into(), 1), ("open".into(), 1)]
        );
        let theme = reopened
            .code_review_themes_for_job(&first_job.id)
            .unwrap()
            .remove(0);
        assert_eq!(theme.status, "open");
        assert!(theme.resolved_head.is_empty());
    }

    #[test]
    fn migration_rebuild_uses_only_published_theme_transitions() {
        let data = tempfile::tempdir().unwrap();
        let database = data.path().join("resolved-theme-observation.sqlite3");
        let store = Store::open(&database).unwrap();
        let published_job = enqueue_backoff_test_job(&store);
        let findings = store
            .save_code_review_result_with_themes(
                &published_job.id,
                "summary",
                "fix the root cause",
                1,
                &[
                    NewCodeReviewFinding {
                        path: "src/published.rs".into(),
                        line: 7,
                        side: "RIGHT".into(),
                        severity: "medium".into(),
                        confidence: "high".into(),
                        title: "Published symptom".into(),
                        body: "Only a published resolver can close this finding.".into(),
                        prompt_for_agents: "Keep unpublished closures open.".into(),
                        sources: Vec::new(),
                    },
                    NewCodeReviewFinding {
                        path: "src/legacy.rs".into(),
                        line: 11,
                        side: "RIGHT".into(),
                        severity: "medium".into(),
                        confidence: "high".into(),
                        title: "Legacy fixed symptom".into(),
                        body: "Legacy closures have no resolver provenance.".into(),
                        prompt_for_agents: "Preserve the legacy closure.".into(),
                        sources: Vec::new(),
                    },
                ],
                &[
                    NewCodeReviewFindingDetails {
                        theme_ids: vec!["published-theme".into()],
                        ..Default::default()
                    },
                    NewCodeReviewFindingDetails {
                        theme_ids: vec!["legacy-theme".into()],
                        ..Default::default()
                    },
                ],
                &[
                    NewCodeReviewTheme {
                        id: "published-theme".into(),
                        root_cause: "published root cause".into(),
                        recommendation: "record the closure transition".into(),
                        observation_kind: trouve_protocol::CodeReviewThemeObservationKind::New,
                        previous_finding_ids: Vec::new(),
                    },
                    NewCodeReviewTheme {
                        id: "legacy-theme".into(),
                        root_cause: "legacy root cause".into(),
                        recommendation: "preserve provenance-free closures".into(),
                        observation_kind: trouve_protocol::CodeReviewThemeObservationKind::New,
                        previous_finding_ids: Vec::new(),
                    },
                    NewCodeReviewTheme {
                        id: "standalone-theme".into(),
                        root_cause: "standalone root cause".into(),
                        recommendation: "record the final publication state".into(),
                        observation_kind: trouve_protocol::CodeReviewThemeObservationKind::New,
                        previous_finding_ids: Vec::new(),
                    },
                ],
                &[],
            )
            .unwrap();
        let published_theme_id = findings[0].theme_ids[0].clone();
        let legacy_theme_id = findings[1].theme_ids[0].clone();
        let standalone_theme_id = store
            .conn
            .lock()
            .unwrap()
            .query_row(
                "SELECT theme_id
                 FROM code_review_theme_observations
                 WHERE job_id = ?1 AND theme_id NOT IN (?2, ?3)",
                params![published_job.id, published_theme_id, legacy_theme_id],
                |row| row.get::<_, String>(0),
            )
            .unwrap();
        let mut unpublished_request = backoff_test_job_request();
        unpublished_request.dedupe_key = "acme/widgets#42:unpublished-resolver".into();
        unpublished_request.head_sha = "3333333333333333333333333333333333333333".into();
        let unpublished_job = store
            .enqueue_code_review_job(&unpublished_request)
            .unwrap()
            .unwrap();
        let stale_unpublished_time = "2099-01-02T03:04:05+00:00";
        let legacy_resolution_time = "1999-01-02T03:04:05+00:00";
        let authoritative_transition_time = {
            let conn = store.conn.lock().unwrap();
            conn.execute(
                "UPDATE code_review_jobs
                 SET review_url = 'https://github.com/acme/widgets/pull/42#pullrequestreview-12',
                     review_published = 1, publication_accepted = 1,
                     publication_order = 1
                 WHERE id = ?1",
                [&published_job.id],
            )
            .unwrap();
            conn.execute(
                "UPDATE code_review_findings
                 SET status = 'fixed', resolved_by_job_id = ?2,
                     resolved_head = ?3, resolved_at = ?4
                 WHERE id = ?1",
                params![
                    findings[0].id,
                    unpublished_job.id,
                    unpublished_job.head_sha,
                    stale_unpublished_time
                ],
            )
            .unwrap();
            conn.execute(
                "UPDATE code_review_findings
                 SET status = 'fixed', resolved_by_job_id = '',
                     resolved_head = ?2, resolved_at = ?3
                 WHERE id = ?1",
                params![
                    findings[1].id,
                    published_job.head_sha,
                    legacy_resolution_time
                ],
            )
            .unwrap();
            conn.execute(
                "UPDATE code_review_themes
                 SET status = 'resolved', resolved_head = 'stale-resolution',
                     updated_at = ?2
                 WHERE id IN (?1, ?3)",
                params![
                    published_theme_id,
                    stale_unpublished_time,
                    standalone_theme_id
                ],
            )
            .unwrap();
            conn.query_row(
                "SELECT MAX(created_at)
                 FROM code_review_theme_observations WHERE job_id = ?1",
                [&published_job.id],
                |row| row.get::<_, String>(0),
            )
            .unwrap()
        };
        drop(store);

        let legacy = Connection::open(&database).unwrap();
        legacy
            .execute_batch(
                "ALTER TABLE code_review_theme_observations RENAME TO authority_observations;
                 CREATE TABLE code_review_theme_observations (
                   theme_id TEXT NOT NULL REFERENCES code_review_themes(id),
                   job_id TEXT NOT NULL REFERENCES code_review_jobs(id),
                   head_sha TEXT NOT NULL,
                   kind TEXT NOT NULL,
                   published INTEGER NOT NULL DEFAULT 0,
                   created_at TEXT NOT NULL,
                   PRIMARY KEY (theme_id, job_id)
                 );
                 INSERT INTO code_review_theme_observations
                   (theme_id, job_id, head_sha, kind, published, created_at)
                 SELECT theme_id, job_id, head_sha, kind, published, created_at
                 FROM authority_observations;
                 DROP TABLE authority_observations;
                 DELETE FROM store_migrations
                 WHERE id = 'code-review-theme-transitions-v1';",
            )
            .unwrap();
        drop(legacy);

        let reopened = Store::open(&database).unwrap();
        let themes = reopened
            .code_review_themes_for_job(&published_job.id)
            .unwrap();
        let published_theme = themes
            .iter()
            .find(|theme| theme.id == published_theme_id)
            .unwrap();
        assert_eq!(published_theme.status, "open");
        assert!(published_theme.resolved_head.is_empty());
        let standalone_theme = themes
            .iter()
            .find(|theme| theme.id == standalone_theme_id)
            .unwrap();
        assert_eq!(standalone_theme.status, "resolved");
        assert_eq!(standalone_theme.resolved_head, published_job.head_sha);
        let legacy_theme = themes
            .iter()
            .find(|theme| theme.id == legacy_theme_id)
            .unwrap();
        assert_eq!(legacy_theme.status, "resolved");
        assert_eq!(legacy_theme.resolved_head, published_job.head_sha);
        let conn = reopened.conn.lock().unwrap();
        for theme_id in [&published_theme_id, &legacy_theme_id, &standalone_theme_id] {
            let (updated_at, transition_count) = conn
                .query_row(
                    "SELECT theme.updated_at, (
                       SELECT COUNT(*) FROM code_review_theme_transitions transition
                       WHERE transition.theme_id = theme.id
                     )
                     FROM code_review_themes theme WHERE theme.id = ?1",
                    [theme_id],
                    |row| Ok((row.get::<_, String>(0)?, row.get::<_, i64>(1)?)),
                )
                .unwrap();
            assert_eq!(updated_at, authoritative_transition_time);
            assert_eq!(transition_count, 1);
        }
    }

    #[test]
    fn rollback_observations_in_transitional_schema_are_rebuilt_once() {
        let data = tempfile::tempdir().unwrap();
        let database = data.path().join("rollback-theme-observation.sqlite3");
        let store = Store::open(&database).unwrap();
        let job = enqueue_backoff_test_job(&store);
        let findings = store
            .save_code_review_result_with_themes(
                &job.id,
                "summary",
                "fix the root cause",
                1,
                &[NewCodeReviewFinding {
                    path: "src/lib.rs".into(),
                    line: 3,
                    side: "RIGHT".into(),
                    severity: "high".into(),
                    confidence: "high".into(),
                    title: "Rollback symptom".into(),
                    body: "Rollback rows already changed their aggregate.".into(),
                    prompt_for_agents: "Preserve the aggregate.".into(),
                    sources: Vec::new(),
                }],
                &[NewCodeReviewFindingDetails {
                    theme_ids: vec!["rollback-theme".into()],
                    ..Default::default()
                }],
                &[NewCodeReviewTheme {
                    id: "rollback-theme".into(),
                    root_cause: "rollback root cause".into(),
                    recommendation: "record authority per observation".into(),
                    observation_kind: trouve_protocol::CodeReviewThemeObservationKind::New,
                    previous_finding_ids: Vec::new(),
                }],
                &[],
            )
            .unwrap();
        let theme_id = findings[0].theme_ids[0].clone();
        drop(store);
        {
            let conn = Connection::open(&database).unwrap();
            // Simulate a rollback writer running after the authority migration
            // added `published` but before per-row provenance was available.
            conn.execute_batch(
                "ALTER TABLE code_review_theme_observations RENAME TO authority_observations;
                 CREATE TABLE code_review_theme_observations (
                   theme_id TEXT NOT NULL REFERENCES code_review_themes(id),
                   job_id TEXT NOT NULL REFERENCES code_review_jobs(id),
                   head_sha TEXT NOT NULL,
                   kind TEXT NOT NULL,
                   published INTEGER NOT NULL DEFAULT 0,
                   created_at TEXT NOT NULL,
                   PRIMARY KEY (theme_id, job_id)
                 );
                 INSERT INTO code_review_theme_observations
                   (theme_id, job_id, head_sha, kind, published, created_at)
                 SELECT theme_id, job_id, head_sha, kind, published, created_at
                 FROM authority_observations;
                 DROP TABLE authority_observations;
                 DELETE FROM store_migrations
                 WHERE id = 'code-review-theme-transitions-v1';",
            )
            .unwrap();
            conn.execute(
                "UPDATE code_review_jobs
                 SET review_published = 1, publication_claimed = 0,
                     publication_order = 0,
                     review_url = 'https://github.com/acme/widgets/pull/42#pullrequestreview-11'
                 WHERE id = ?1",
                [&job.id],
            )
            .unwrap();
            // The rollback writer omits provenance and eagerly updates the
            // aggregate theme, while SQLite supplies `published = 0`.
            conn.execute(
                "DELETE FROM code_review_theme_observations WHERE job_id = ?1",
                [&job.id],
            )
            .unwrap();
            conn.execute(
                "INSERT INTO code_review_theme_observations
                   (theme_id, job_id, head_sha, kind, created_at)
                 VALUES (?1, ?2, ?3, 'recurrence', ?4)",
                params![
                    theme_id,
                    job.id,
                    job.head_sha,
                    chrono::Utc::now().to_rfc3339()
                ],
            )
            .unwrap();
            conn.execute(
                "UPDATE code_review_themes
                 SET status = 'open', last_seen_head = ?2,
                     resolved_head = '', recurrence_count = 5
                 WHERE id = ?1",
                params![theme_id, job.head_sha],
            )
            .unwrap();
        }

        let reopened = Store::open(&database).unwrap();
        let observation = reopened
            .conn
            .lock()
            .unwrap()
            .query_row(
                "SELECT published, publication_managed
                 FROM code_review_theme_observations WHERE job_id = ?1",
                [&job.id],
                |row| Ok((row.get::<_, bool>(0)?, row.get::<_, bool>(1)?)),
            )
            .unwrap();
        assert_eq!(observation, (true, true));
        let themes = reopened.code_review_themes_for_job(&job.id).unwrap();
        assert_eq!(themes[0].status, "open");
        assert_eq!(themes[0].last_seen_head, job.head_sha);
        assert!(themes[0].resolved_head.is_empty());
        assert_eq!(themes[0].recurrence_count, 1);
    }

    #[test]
    fn observation_recovery_replays_durable_publication_order() {
        let store = Store::open_in_memory().unwrap();
        let first_job = enqueue_backoff_test_job(&store);
        let findings = store
            .save_code_review_result_with_themes(
                &first_job.id,
                "summary",
                "fix the root cause",
                1,
                &[NewCodeReviewFinding {
                    path: "src/lib.rs".into(),
                    line: 3,
                    side: "RIGHT".into(),
                    severity: "high".into(),
                    confidence: "high".into(),
                    title: "Ordered symptom".into(),
                    body: "Publication order is authoritative.".into(),
                    prompt_for_agents: "Preserve it.".into(),
                    sources: Vec::new(),
                }],
                &[NewCodeReviewFindingDetails {
                    theme_ids: vec!["ordered-theme".into()],
                    ..Default::default()
                }],
                &[NewCodeReviewTheme {
                    id: "ordered-theme".into(),
                    root_cause: "ordered root cause".into(),
                    recommendation: "replay publication order".into(),
                    observation_kind: trouve_protocol::CodeReviewThemeObservationKind::New,
                    previous_finding_ids: Vec::new(),
                }],
                &[],
            )
            .unwrap();
        let theme_id = findings[0].theme_ids[0].clone();
        let mut second_request = backoff_test_job_request();
        second_request.dedupe_key = "acme/widgets#42:published-first".into();
        second_request.head_sha = "3333333333333333333333333333333333333333".into();
        let second_job = store
            .enqueue_code_review_job(&second_request)
            .unwrap()
            .unwrap();

        let mut conn = store.conn.lock().unwrap();
        conn.execute(
            "UPDATE code_review_jobs
             SET review_published = 1,
                 publication_order = CASE id WHEN ?1 THEN 2 ELSE 1 END
             WHERE id IN (?1, ?2)",
            params![first_job.id, second_job.id],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO code_review_theme_observations
               (theme_id, job_id, head_sha, kind, published,
                publication_managed, created_at)
             VALUES (?1, ?2, ?3, 'continuation', 0, 1, ?4)",
            params![
                theme_id,
                second_job.id,
                second_job.head_sha,
                chrono::Utc::now().to_rfc3339()
            ],
        )
        .unwrap();
        conn.execute(
            "UPDATE code_review_themes SET status = 'pending', last_seen_head = ''
             WHERE id = ?1",
            [&theme_id],
        )
        .unwrap();

        promote_published_code_review_theme_observations(&mut conn).unwrap();
        let state = conn
            .query_row(
                "SELECT status, last_seen_head FROM code_review_themes WHERE id = ?1",
                [&theme_id],
                |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
            )
            .unwrap();
        assert_eq!(state, ("open".into(), first_job.head_sha));
    }

    #[test]
    fn observation_recovery_normalizes_mixed_legacy_and_modern_orders() {
        let store = Store::open_in_memory().unwrap();
        for index in 0..4 {
            let mut request = backoff_test_job_request();
            request.dedupe_key = format!("acme/widgets#{}:rowid-padding", 100 + index);
            request.pull_number = 100 + index;
            store.enqueue_code_review_job(&request).unwrap().unwrap();
        }

        let legacy_job = enqueue_backoff_test_job(&store);
        let findings = store
            .save_code_review_result_with_themes(
                &legacy_job.id,
                "summary",
                "fix the root cause",
                1,
                &[NewCodeReviewFinding {
                    path: "src/lib.rs".into(),
                    line: 3,
                    side: "RIGHT".into(),
                    severity: "high".into(),
                    confidence: "high".into(),
                    title: "Mixed-order symptom".into(),
                    body: "Publication order domains must not be mixed.".into(),
                    prompt_for_agents: "Normalize the sequence.".into(),
                    sources: Vec::new(),
                }],
                &[NewCodeReviewFindingDetails {
                    theme_ids: vec!["mixed-order-theme".into()],
                    ..Default::default()
                }],
                &[NewCodeReviewTheme {
                    id: "mixed-order-theme".into(),
                    root_cause: "mixed publication order".into(),
                    recommendation: "use one per-pull sequence".into(),
                    observation_kind: trouve_protocol::CodeReviewThemeObservationKind::New,
                    previous_finding_ids: Vec::new(),
                }],
                &[],
            )
            .unwrap();
        let theme_id = findings[0].theme_ids[0].clone();
        let mut modern_request = backoff_test_job_request();
        modern_request.dedupe_key = "acme/widgets#42:modern-publication".into();
        modern_request.head_sha = "3333333333333333333333333333333333333333".into();
        let modern_job = store
            .enqueue_code_review_job(&modern_request)
            .unwrap()
            .unwrap();
        let mut earlier_request = backoff_test_job_request();
        earlier_request.dedupe_key = "acme/widgets#42:earlier-publication".into();
        earlier_request.head_sha = "4444444444444444444444444444444444444444".into();
        let earlier_job = store
            .enqueue_code_review_job(&earlier_request)
            .unwrap()
            .unwrap();
        let mut mixed_evidence_request = backoff_test_job_request();
        mixed_evidence_request.dedupe_key = "acme/widgets#42:mixed-evidence".into();
        mixed_evidence_request.head_sha = "5555555555555555555555555555555555555555".into();
        let mixed_evidence_job = store
            .enqueue_code_review_job(&mixed_evidence_request)
            .unwrap()
            .unwrap();

        let mut conn = store.conn.lock().unwrap();
        conn.execute(
            "UPDATE code_review_jobs
             SET review_published = 1,
                 publication_order = CASE id
                   WHEN ?1 THEN 0 WHEN ?2 THEN 2 WHEN ?3 THEN 1 ELSE 0 END,
                 review_url = CASE id
                   WHEN ?1 THEN 'https://github.com/acme/widgets/pull/42#pullrequestreview-20'
                   WHEN ?2 THEN 'https://github.com/acme/widgets/pull/42#pullrequestreview-30'
                   WHEN ?3 THEN 'https://github.com/acme/widgets/pull/42#pullrequestreview-10'
                   ELSE '' END,
                 completed_at = CASE id
                   WHEN ?1 THEN '2026-08-20T00:00:40Z'
                   WHEN ?2 THEN '2026-08-20T00:00:10Z'
                   WHEN ?3 THEN '2026-08-20T00:00:30Z'
                   ELSE '2026-08-20T00:00:05Z' END
             WHERE id IN (?1, ?2, ?3, ?4)",
            params![
                legacy_job.id,
                modern_job.id,
                earlier_job.id,
                mixed_evidence_job.id
            ],
        )
        .unwrap();
        for job in [&modern_job, &earlier_job] {
            conn.execute(
                "INSERT INTO code_review_theme_observations
               (theme_id, job_id, head_sha, kind, published,
                publication_managed, created_at)
             VALUES (?1, ?2, ?3, 'continuation', 0, 1, ?4)",
                params![
                    theme_id,
                    job.id,
                    job.head_sha,
                    chrono::Utc::now().to_rfc3339()
                ],
            )
            .unwrap();
        }
        conn.execute(
            "UPDATE code_review_themes SET status = 'pending', last_seen_head = ''
             WHERE id = ?1",
            [&theme_id],
        )
        .unwrap();

        normalize_code_review_publication_orders(&mut conn).unwrap();
        let publication_order = |job_id: &str| {
            conn.query_row(
                "SELECT publication_order FROM code_review_jobs WHERE id = ?1",
                [job_id],
                |row| row.get::<_, i64>(0),
            )
            .unwrap()
        };
        // The two established orders disagree with creation rowid and their
        // lifecycle timestamps run opposite to GitHub review-id order. Their
        // relative order survives, review id 20 is placed between ids 10 and
        // 30, and the no-id fallback remains deterministic and transitive.
        assert_eq!(publication_order(&earlier_job.id), 1);
        assert_eq!(publication_order(&legacy_job.id), 2);
        assert_eq!(publication_order(&modern_job.id), 3);
        assert_eq!(publication_order(&mixed_evidence_job.id), 4);

        promote_published_code_review_theme_observations(&mut conn).unwrap();
        let state = conn
            .query_row(
                "SELECT status, last_seen_head FROM code_review_themes WHERE id = ?1",
                [&theme_id],
                |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
            )
            .unwrap();
        assert_eq!(state, ("open".into(), modern_job.head_sha));
    }

    fn backoff_test_job_request() -> NewCodeReviewJob {
        NewCodeReviewJob {
            dedupe_key: "acme/widgets#42:backoff".into(),
            installation_id: 7,
            repository: "acme/widgets".into(),
            pull_number: 42,
            pull_title: "Ship widgets".into(),
            pull_body: String::new(),
            pull_url: "https://github.com/acme/widgets/pull/42".into(),
            head_sha: "2222222222222222222222222222222222222222".into(),
            review_base_sha: "1111111111111111111111111111111111111111".into(),
            base_ref: "main".into(),
            head_ref: "ship".into(),
            scope: trouve_protocol::CodeReviewJobScope::Incremental,
            trigger: "automatic".into(),
            retry_of: None,
            model: Some("provider/default".into()),
            coordinator_thinking_level: None,
            router_model: None,
            router_thinking_level: None,
            analyst_model: None,
            analyst_thinking_level: None,
            prompt: "Review it".into(),
            reviewers: crate::reviewers::built_in_reviewers()
                .into_iter()
                .take(1)
                .collect(),
            routing_mode: trouve_protocol::CodeReviewRoutingMode::Manual,
            semantic_routing: false,
            included_reviewer_ids: Vec::new(),
            excluded_reviewer_ids: Vec::new(),
            config_hash: "config".into(),
        }
    }

    fn enqueue_backoff_test_job(store: &Store) -> trouve_protocol::CodeReviewJob {
        store
            .enqueue_code_review_job(&backoff_test_job_request())
            .unwrap()
            .unwrap()
    }

    #[test]
    fn unpublished_dispatch_recovery_is_supersession_aware() {
        let store = Store::open_in_memory().unwrap();
        let first = enqueue_backoff_test_job(&store);
        assert_eq!(
            store.claim_code_review_job().unwrap().unwrap().job.id,
            first.id
        );
        assert!(store.claim_code_review_publication(&first.id).unwrap());
        assert!(
            store
                .mark_code_review_publication_dispatched(&first.id)
                .unwrap()
        );
        store
            .finish_code_review_job(&first.id, "failed", "GitHub API 500", "")
            .unwrap();
        // No newer round has published yet. Even repeated definitive marker
        // absence cannot prove that GitHub did not create the review before
        // the client lost the POST response, so the dispatch stays sticky.
        assert_eq!(
            store
                .resolve_code_review_publication_absence(&first.id, 2)
                .unwrap(),
            CodeReviewPublicationAbsenceOutcome::Pending
        );
        assert_eq!(
            store
                .resolve_code_review_publication_absence(&first.id, 2)
                .unwrap(),
            CodeReviewPublicationAbsenceOutcome::Quarantined
        );
        let record = store.code_review_job(&first.id).unwrap().unwrap();
        assert!(record.publication_claimed);
        assert!(record.publication_dispatched);
        assert!(
            record
                .job
                .check_sync_error
                .contains("outcome remains ambiguous")
        );
        assert!(
            store
                .code_review_jobs_with_projection_errors(10)
                .unwrap()
                .iter()
                .all(|job| job.id != first.id),
            "a quarantined dispatch must pause automatic scans without becoming repostable"
        );
        store
            .conn
            .lock()
            .unwrap()
            .execute(
                "UPDATE code_review_jobs SET projection_retry_at = ?2 WHERE id = ?1",
                params![first.id, "1970-01-01T00:00:00Z"],
            )
            .unwrap();
        assert!(
            store
                .code_review_jobs_with_projection_errors(10)
                .unwrap()
                .iter()
                .any(|job| job.id == first.id),
            "quarantine must resume low-frequency marker-only reconciliation"
        );
        assert_eq!(
            store
                .resolve_code_review_publication_absence(&first.id, 2)
                .unwrap(),
            CodeReviewPublicationAbsenceOutcome::Quarantined
        );
        let record = store.code_review_job(&first.id).unwrap().unwrap();
        assert!(record.publication_claimed);
        assert!(record.publication_dispatched);

        // An accepted publication can also remain marker-unreconciled. It
        // stays recoverable while it is current, but a later accepted round
        // must terminally supersede it just like an ambiguous dispatch.
        let mut accepted_superseded_request = backoff_test_job_request();
        accepted_superseded_request.dedupe_key = "acme/widgets#42:accepted-superseded".into();
        accepted_superseded_request.head_sha = "2828282828282828282828282828282828282828".into();
        let accepted_superseded = store
            .enqueue_code_review_job(&accepted_superseded_request)
            .unwrap()
            .unwrap();
        assert_eq!(
            store.claim_code_review_job().unwrap().unwrap().job.id,
            accepted_superseded.id
        );
        assert!(
            store
                .claim_code_review_publication(&accepted_superseded.id)
                .unwrap()
        );
        assert!(
            store
                .mark_code_review_publication_dispatched(&accepted_superseded.id)
                .unwrap()
        );
        assert!(
            store
                .mark_code_review_publication_accepted(&accepted_superseded.id)
                .unwrap()
        );
        store
            .finish_code_review_job(
                &accepted_superseded.id,
                "failed",
                "accepted publication marker is not visible yet",
                "",
            )
            .unwrap();

        // A second dispatched round is overtaken while it is awaiting marker
        // reconciliation.
        let mut superseded_request = backoff_test_job_request();
        superseded_request.dedupe_key = "acme/widgets#42:superseded".into();
        superseded_request.head_sha = "2929292929292929292929292929292929292929".into();
        let superseded = store
            .enqueue_code_review_job(&superseded_request)
            .unwrap()
            .unwrap();
        assert_eq!(
            store.claim_code_review_job().unwrap().unwrap().job.id,
            superseded.id
        );
        assert!(store.claim_code_review_publication(&superseded.id).unwrap());
        assert!(
            store
                .mark_code_review_publication_dispatched(&superseded.id)
                .unwrap()
        );
        store
            .finish_code_review_job(&superseded.id, "failed", "GitHub API 500", "")
            .unwrap();

        // A newer round in flight fences the old dispatch without terminally
        // superseding it until GitHub has accepted the newer POST.
        let mut newer_request = backoff_test_job_request();
        newer_request.dedupe_key = "acme/widgets#42:newer".into();
        newer_request.head_sha = "3333333333333333333333333333333333333333".into();
        let newer = store
            .enqueue_code_review_job(&newer_request)
            .unwrap()
            .unwrap();
        assert_eq!(
            store.claim_code_review_job().unwrap().unwrap().job.id,
            newer.id
        );
        assert!(store.claim_code_review_publication(&newer.id).unwrap());
        assert_eq!(
            store
                .resolve_code_review_publication_absence(&accepted_superseded.id, 1)
                .unwrap(),
            CodeReviewPublicationAbsenceOutcome::AcceptedPending,
            "an accepted current publication remains recoverable while a newer POST is only in flight"
        );
        assert_eq!(
            store
                .resolve_code_review_publication_absence(&superseded.id, 1)
                .unwrap(),
            CodeReviewPublicationAbsenceOutcome::NewerPublicationPending,
            "a claimed newer publication fences the older dispatch"
        );
        assert!(
            store
                .mark_code_review_publication_dispatched(&newer.id)
                .unwrap()
        );
        assert_eq!(
            store
                .resolve_code_review_publication_absence(&superseded.id, 1)
                .unwrap(),
            CodeReviewPublicationAbsenceOutcome::NewerPublicationPending,
            "a dispatched newer publication fences the older dispatch"
        );
        assert!(
            store
                .mark_code_review_publication_accepted(&newer.id)
                .unwrap()
        );
        assert_eq!(
            store
                .resolve_code_review_publication_absence(&superseded.id, 1)
                .unwrap(),
            CodeReviewPublicationAbsenceOutcome::Superseded,
            "an accepted newer publication terminally supersedes the old dispatch"
        );
        assert_eq!(
            store
                .resolve_code_review_publication_absence(&accepted_superseded.id, 1)
                .unwrap(),
            CodeReviewPublicationAbsenceOutcome::Superseded,
            "an accepted newer publication also supersedes an older accepted publication"
        );
        let accepted_superseded_record = store
            .code_review_job(&accepted_superseded.id)
            .unwrap()
            .unwrap();
        assert!(
            accepted_superseded_record
                .job
                .check_sync_error
                .contains("newer round")
        );
        assert!(
            store
                .code_review_jobs_with_projection_errors(10)
                .unwrap()
                .iter()
                .all(|job| job.id != accepted_superseded.id),
            "a superseded accepted publication must leave the repair queue"
        );
        assert!(
            store
                .reconcile_code_review_publication(&newer.id, "https://example/review", &[])
                .unwrap()
        );
        assert_eq!(
            store
                .resolve_code_review_publication_absence(&newer.id, 1)
                .unwrap(),
            CodeReviewPublicationAbsenceOutcome::Published,
            "a stale absence observation is a no-op after publication is reconciled"
        );
        store
            .finish_code_review_job(&newer.id, "succeeded", "", "published")
            .unwrap();
        let mut latest_request = backoff_test_job_request();
        latest_request.dedupe_key = "acme/widgets#42:latest".into();
        latest_request.head_sha = "3434343434343434343434343434343434343434".into();
        let latest = store
            .enqueue_code_review_job(&latest_request)
            .unwrap()
            .unwrap();
        assert_eq!(
            store.claim_code_review_job().unwrap().unwrap().job.id,
            latest.id
        );
        assert!(store.claim_code_review_publication(&latest.id).unwrap());
        assert!(
            store
                .mark_code_review_publication_dispatched(&latest.id)
                .unwrap()
        );
        assert!(
            store
                .mark_code_review_publication_accepted(&latest.id)
                .unwrap()
        );
        let reconciled_before_stale_absence = store.code_review_job(&newer.id).unwrap().unwrap();
        assert_eq!(
            store
                .resolve_code_review_publication_absence(&newer.id, 1)
                .unwrap(),
            CodeReviewPublicationAbsenceOutcome::Published,
            "a newer accepted round cannot make a stale absence overwrite a reconciled publication"
        );
        let reconciled_after_stale_absence = store.code_review_job(&newer.id).unwrap().unwrap();
        assert!(reconciled_after_stale_absence.review_published);
        assert_eq!(
            reconciled_after_stale_absence.job.check_sync_error,
            reconciled_before_stale_absence.job.check_sync_error
        );
    }

    #[test]
    fn current_result_save_rejects_cancelled_or_replaced_jobs_before_writing() {
        let store = Store::open_in_memory().unwrap();
        let cancelled = enqueue_backoff_test_job(&store);
        assert_eq!(
            store.claim_code_review_job().unwrap().unwrap().job.id,
            cancelled.id
        );
        store
            .request_code_review_job_cancel(&cancelled.id)
            .unwrap()
            .unwrap();
        let save_empty_result = |job_id: &str, summary: &str| {
            store.save_current_code_review_result_with_adjudication(
                job_id,
                summary,
                "prompt",
                0,
                &[],
                &[],
                &[],
                &[],
                &[],
            )
        };
        assert!(
            save_empty_result(&cancelled.id, "cancelled result")
                .unwrap()
                .is_none()
        );
        assert!(
            store
                .code_review_job(&cancelled.id)
                .unwrap()
                .unwrap()
                .summary
                .is_empty()
        );

        let mut older_request = backoff_test_job_request();
        older_request.dedupe_key = "acme/widgets#42:older-result".into();
        let older = store
            .enqueue_code_review_job(&older_request)
            .unwrap()
            .unwrap();
        assert_eq!(
            store.claim_code_review_job().unwrap().unwrap().job.id,
            older.id
        );
        let mut replacement_request = backoff_test_job_request();
        replacement_request.dedupe_key = "acme/widgets#42:replacement-result".into();
        store
            .enqueue_code_review_job(&replacement_request)
            .unwrap()
            .unwrap();
        assert!(
            save_empty_result(&older.id, "replaced result")
                .unwrap()
                .is_none()
        );
        assert!(
            store
                .code_review_job(&older.id)
                .unwrap()
                .unwrap()
                .summary
                .is_empty()
        );
    }

    #[test]
    fn current_result_save_accepts_the_current_running_job() {
        let store = Store::open_in_memory().unwrap();
        let current = enqueue_backoff_test_job(&store);
        assert_eq!(
            store.claim_code_review_job().unwrap().unwrap().job.id,
            current.id
        );

        let saved = store
            .save_current_code_review_result_with_adjudication(
                &current.id,
                "Current result",
                "Current prompt",
                0,
                &[],
                &[],
                &[],
                &[],
                &[],
            )
            .unwrap();

        assert!(saved.is_some());
        let record = store.code_review_job(&current.id).unwrap().unwrap();
        assert_eq!(record.summary, "Current result");
        assert_eq!(record.prompt_for_agents, "Current prompt");
    }

    #[test]
    fn staged_result_can_be_discarded_before_publication() {
        let store = Store::open_in_memory().unwrap();
        let current = enqueue_backoff_test_job(&store);
        assert_eq!(
            store.claim_code_review_job().unwrap().unwrap().job.id,
            current.id
        );
        let now = chrono::Utc::now().to_rfc3339();
        {
            let conn = store.conn.lock().unwrap();
            conn.execute(
                "INSERT INTO code_review_themes
                    (id, repository, pull_number, root_cause, recommendation, status,
                     first_seen_head, last_seen_head, resolved_head, recurrence_count,
                     created_at, updated_at)
                 VALUES ('transition-theme', ?1, ?2, 'original root cause',
                         'original recommendation', 'open', ?3, ?3, '', 0, ?4, ?4)",
                params![
                    current.repository,
                    current.pull_number as i64,
                    current.head_sha,
                    now,
                ],
            )
            .unwrap();
            conn.execute(
                "INSERT INTO code_review_theme_transitions
                    (theme_id, job_id, status, last_seen_head, resolved_head,
                     recurrence_count, transitioned_at)
                 VALUES ('transition-theme', ?1, 'open', ?2, '', 0, ?3)",
                params![current.id, current.head_sha, now],
            )
            .unwrap();
        }
        let findings = [NewCodeReviewFinding {
            path: "src/lib.rs".into(),
            line: 7,
            side: "RIGHT".into(),
            severity: "medium".into(),
            confidence: "high".into(),
            title: "Staged finding".into(),
            body: "Only valid for the staged revision.".into(),
            prompt_for_agents: "Fix the staged finding.".into(),
            sources: Vec::new(),
        }];
        let finding_details = [NewCodeReviewFindingDetails {
            theme_ids: vec!["staged-theme".into(), "transition-theme".into()],
            ..Default::default()
        }];
        let themes = [
            NewCodeReviewTheme {
                id: "staged-theme".into(),
                root_cause: "staged root cause".into(),
                recommendation: "staged recommendation".into(),
                observation_kind: trouve_protocol::CodeReviewThemeObservationKind::New,
                previous_finding_ids: Vec::new(),
            },
            NewCodeReviewTheme {
                id: "transition-theme".into(),
                root_cause: "rejected replacement root cause".into(),
                recommendation: "rejected replacement recommendation".into(),
                observation_kind: trouve_protocol::CodeReviewThemeObservationKind::Continuation,
                previous_finding_ids: Vec::new(),
            },
        ];
        let rejections = [trouve_protocol::CodeReviewCandidateRejection {
            candidate_id: "rejected".into(),
            task_id: "task".into(),
            reviewer_id: "correctness".into(),
            reviewer_name: "Correctness".into(),
            path: "src/lib.rs".into(),
            line: 8,
            side: "RIGHT".into(),
            severity: "low".into(),
            confidence: "high".into(),
            title: "Rejected candidate".into(),
            body: "Not actionable.".into(),
            reason: "non_actionable: no current defect".into(),
        }];
        let unadjudicated = [trouve_protocol::CodeReviewUnadjudicatedCandidate {
            candidate_id: "unresolved".into(),
            task_id: "task".into(),
            reviewer_id: "correctness".into(),
            reviewer_name: "Correctness".into(),
            path: "src/lib.rs".into(),
            line: 9,
            side: "RIGHT".into(),
            severity: "medium".into(),
            confidence: "high".into(),
            title: "Unresolved candidate".into(),
            body: "The editor omitted a decision.".into(),
        }];

        let saved = store
            .save_current_code_review_result_with_adjudication(
                &current.id,
                "Staged result",
                "Staged prompt",
                3,
                &findings,
                &finding_details,
                &themes,
                &rejections,
                &unadjudicated,
            )
            .unwrap()
            .unwrap();

        assert_eq!(saved.len(), 1);
        let staged = store.code_review_job(&current.id).unwrap().unwrap();
        assert!(!staged.publication_claimed);
        let staged_detail = store.code_review_job_detail(&current.id).unwrap().unwrap();
        assert_eq!(staged_detail.findings.len(), 1);
        assert_eq!(staged_detail.candidate_rejections.len(), 1);
        assert_eq!(staged_detail.unadjudicated_candidates.len(), 1);
        let mut replacement_request = backoff_test_job_request();
        replacement_request.dedupe_key = "acme/widgets#42:replacement-after-stage".into();
        store
            .enqueue_code_review_job(&replacement_request)
            .unwrap()
            .unwrap();
        assert!(!store.claim_code_review_publication(&current.id).unwrap());
        assert!(
            store
                .discard_unaccepted_code_review_result(&current.id)
                .unwrap()
        );

        let discarded = store.code_review_job(&current.id).unwrap().unwrap();
        assert!(!discarded.publication_claimed);
        assert_eq!(discarded.summary, "");
        assert_eq!(discarded.prompt_for_agents, "");
        assert_eq!(discarded.job.candidate_issue_count, 0);
        assert_eq!(discarded.job.issue_count, 0);
        let detail = store.code_review_job_detail(&current.id).unwrap().unwrap();
        assert!(detail.findings.is_empty());
        assert!(detail.candidate_rejections.is_empty());
        assert!(detail.unadjudicated_candidates.is_empty());
        let conn = store.conn.lock().unwrap();
        let observations: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM code_review_theme_observations WHERE job_id = ?1",
                params![current.id],
                |row| row.get(0),
            )
            .unwrap();
        let orphan_themes: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM code_review_themes WHERE root_cause = 'staged root cause'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        let retained_theme: (String, String) = conn
            .query_row(
                "SELECT root_cause, recommendation FROM code_review_themes
                 WHERE id = 'transition-theme'",
                [],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        let transitions: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM code_review_theme_transitions
                 WHERE theme_id = 'transition-theme'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(observations, 0);
        assert_eq!(orphan_themes, 0);
        assert_eq!(retained_theme.0, "original root cause");
        assert_eq!(retained_theme.1, "original recommendation");
        assert_eq!(transitions, 1);
    }

    #[test]
    fn watermark_backfill_uses_last_published_head_not_effective_base() {
        let store = Store::open_in_memory().unwrap();
        let job = enqueue_backoff_test_job(&store);
        let published_head = "3333333333333333333333333333333333333333";
        let fallback_base = "4444444444444444444444444444444444444444";
        store
            .mark_code_review_published(
                "acme/widgets",
                42,
                "1111111111111111111111111111111111111111",
                published_head,
            )
            .unwrap();
        {
            let mut conn = store.conn.lock().unwrap();
            conn.execute(
                "UPDATE code_review_jobs
                 SET review_base_sha = ?2, review_watermark_sha = '' WHERE id = ?1",
                params![job.id, fallback_base],
            )
            .unwrap();
            conn.execute(
                "DELETE FROM store_migrations WHERE id = 'code-review-watermark-backfill-v1'",
                [],
            )
            .unwrap();
            backfill_code_review_watermarks(&mut conn).unwrap();
        }

        let migrated = store.code_review_job(&job.id).unwrap().unwrap().job;
        assert_eq!(migrated.review_base_sha, fallback_base);
        assert_eq!(migrated.review_watermark_sha, published_head);
    }

    #[test]
    fn draft_stale_dedupe_normalization_runs_on_reopen_and_is_idempotent() {
        let data = tempfile::tempdir().unwrap();
        let database = data.path().join("draft-stale.sqlite3");
        let legacy = {
            let store = Store::open(&database).unwrap();
            let legacy = enqueue_backoff_test_job(&store);
            assert_eq!(
                store.claim_code_review_job().unwrap().unwrap().job.id,
                legacy.id
            );
            assert!(
                store
                    .finish_code_review_job(
                        &legacy.id,
                        "stale",
                        "",
                        "stale: pull request is a draft; automatic review stopped",
                    )
                    .unwrap()
                    .is_some()
            );
            legacy
        };

        let normalized_key = {
            let store = Store::open(&database).unwrap();
            let normalized_key = store
                .conn
                .lock()
                .unwrap()
                .query_row(
                    "SELECT dedupe_key FROM code_review_jobs WHERE id = ?1",
                    params![legacy.id],
                    |row| row.get::<_, String>(0),
                )
                .unwrap();
            let replacement = enqueue_backoff_test_job(&store);
            assert_ne!(replacement.id, legacy.id);
            normalized_key
        };

        let store = Store::open(&database).unwrap();
        let reopened_key = store
            .conn
            .lock()
            .unwrap()
            .query_row(
                "SELECT dedupe_key FROM code_review_jobs WHERE id = ?1",
                params![legacy.id],
                |row| row.get::<_, String>(0),
            )
            .unwrap();
        assert_eq!(reopened_key, normalized_key);
    }

    #[test]
    fn a_latest_superseded_attempt_does_not_resurrect_an_older_success() {
        let store = Store::open_in_memory().unwrap();
        let job = enqueue_backoff_test_job(&store);
        store.claim_code_review_job().unwrap().unwrap();
        let reviewer = crate::reviewers::built_in_reviewers().remove(0);
        let create = |prompt: &str| {
            store
                .create_code_review_task(&NewCodeReviewTask {
                    job_id: job.id.clone(),
                    role: trouve_protocol::CodeReviewTaskRole::Reviewer,
                    reviewer_id: Some(reviewer.id.clone()),
                    reviewer_name: reviewer.name.clone(),
                    batch_index: 0,
                    batch_count: 1,
                    model: Some("provider/default".into()),
                    prompt: prompt.into(),
                })
                .unwrap()
        };
        let old = create("old prompt");
        store
            .start_code_review_task(&old.id, "session", "thread", "provider/default")
            .unwrap();
        store
            .finish_code_review_task(&old.id, "succeeded", "old output", 0, "")
            .unwrap();
        let replacement = create("new prompt");
        store
            .supersede_code_review_tasks_for_prompt_change(
                &job.id,
                std::slice::from_ref(&replacement.id),
                1,
            )
            .unwrap();

        assert!(
            store
                .latest_code_review_reviewer_tasks(&job.id)
                .unwrap()
                .is_empty()
        );
        assert_eq!(store.completed_code_review_personas(&job.id).unwrap(), 0);
    }

    #[test]
    fn legacy_default_reviewers_gain_automatic_routing_only_once() {
        const LEGACY_DEFAULTS: &str = r#"["correctness","security","api-compatibility","testing"]"#;
        let conn = Connection::open_in_memory().unwrap();
        conn.execute_batch(SCHEMA).unwrap();
        conn.execute(
            "INSERT INTO code_review_repositories
                    (repository, installation_id, identity_ids, routing_mode,
                     semantic_routing, updated_at)
             VALUES ('acme/widgets', 7, ?1, 'core', 0, '2026-01-01T00:00:00Z')",
            [LEGACY_DEFAULTS],
        )
        .unwrap();

        migrate_automatic_code_review_routing(&conn).unwrap();
        let migrated: (String, String, bool) = conn
            .query_row(
                "SELECT identity_ids, routing_mode, semantic_routing
                 FROM code_review_repositories
                 WHERE repository = 'acme/widgets'",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .unwrap();
        assert_eq!(
            serde_json::from_str::<Vec<String>>(&migrated.0).unwrap(),
            crate::reviewers::default_reviewer_ids()
        );
        assert_eq!(migrated.1, "auto");
        assert!(migrated.2);

        // Once migrated, an explicit return to Core is a user choice and must
        // survive subsequent startups.
        conn.execute(
            "UPDATE code_review_repositories
             SET identity_ids = ?1, routing_mode = 'core', semantic_routing = 0
             WHERE repository = 'acme/widgets'",
            [LEGACY_DEFAULTS],
        )
        .unwrap();
        migrate_automatic_code_review_routing(&conn).unwrap();
        let retained: (String, String, bool) = conn
            .query_row(
                "SELECT identity_ids, routing_mode, semantic_routing
                 FROM code_review_repositories
                 WHERE repository = 'acme/widgets'",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .unwrap();
        assert_eq!(retained.0, LEGACY_DEFAULTS);
        assert_eq!(retained.1, "core");
        assert!(!retained.2);
    }

    #[test]
    fn terminal_code_review_jobs_are_cleanup_eligible() {
        let store = Store::open_in_memory().unwrap();
        let finish_job = |status: &str, suffix: &str| {
            let queued = store
                .enqueue_code_review_job(&NewCodeReviewJob {
                    dedupe_key: format!("acme/widgets#42:{suffix}"),
                    installation_id: 7,
                    repository: "acme/widgets".into(),
                    pull_number: 42,
                    pull_title: "Ship widgets".into(),
                    pull_body: String::new(),
                    pull_url: "https://github.com/acme/widgets/pull/42".into(),
                    head_sha: "1111111111111111111111111111111111111111".into(),
                    review_base_sha: "0000000000000000000000000000000000000000".into(),
                    base_ref: "0000000000000000000000000000000000000000".into(),
                    head_ref: "ship".into(),
                    scope: trouve_protocol::CodeReviewJobScope::Incremental,
                    trigger: "automatic".into(),
                    retry_of: None,
                    model: None,
                    coordinator_thinking_level: None,
                    router_model: None,
                    router_thinking_level: None,
                    analyst_model: None,
                    analyst_thinking_level: None,
                    prompt: String::new(),
                    reviewers: Vec::new(),
                    routing_mode: trouve_protocol::CodeReviewRoutingMode::Manual,
                    semantic_routing: false,
                    included_reviewer_ids: Vec::new(),
                    excluded_reviewer_ids: Vec::new(),
                    config_hash: "config".into(),
                })
                .unwrap()
                .unwrap();
            assert_eq!(
                store.claim_code_review_job().unwrap().unwrap().job.id,
                queued.id
            );
            let session_id = format!("se_{suffix}");
            store
                .set_code_review_job_session(&queued.id, &session_id, &format!("th_{suffix}"))
                .unwrap();
            store
                .finish_code_review_job(&queued.id, status, "", status)
                .unwrap();
            (queued.id, session_id)
        };

        let mut expected = [
            finish_job("succeeded", "succeeded"),
            finish_job("failed", "failed"),
            finish_job("stale", "stale"),
        ];
        let mut pending = store.pending_code_review_job_cleanups().unwrap();
        expected.sort();
        pending.sort();
        assert_eq!(pending, expected);

        for (job_id, session_id) in expected {
            store
                .complete_code_review_job_cleanup(&job_id, &session_id)
                .unwrap();
            let job = store.code_review_job(&job_id).unwrap().unwrap().job;
            assert!(job.session_id.is_none());
            assert!(job.thread_id.is_none());
        }
        assert!(store.pending_code_review_job_cleanups().unwrap().is_empty());
    }

    #[test]
    fn custom_reviewer_profiles_are_durable_and_removed_from_policies() {
        let store = Store::open_in_memory().unwrap();
        let reviewer = trouve_protocol::ReviewerProfile {
            id: "custom:domain".into(),
            name: "Domain invariants".into(),
            prompt: "Check widget state transitions.".into(),
            model: Some("openai/gpt-5".into()),
            default_thinking_level: Some("high".into()),
            built_in: false,
        };
        store.upsert_reviewer_profile(&reviewer).unwrap();
        let reviewers = store.list_custom_reviewer_profiles().unwrap();
        assert_eq!(reviewers.as_slice(), std::slice::from_ref(&reviewer));
        let excluded_built_ins = crate::reviewers::built_in_reviewers()
            .into_iter()
            .map(|built_in| built_in.id)
            .collect::<Vec<_>>();
        let unrelated_exclusions = excluded_built_ins.clone();
        store
            .update_code_review_repository(&trouve_protocol::UpdateCodeReviewRepositoryRequest {
                installation_id: 7,
                repository: "acme/widgets".into(),
                mode: trouve_protocol::CodeReviewMode::Automatic,
                model: None,
                coordinator_thinking_level: None,
                router_model: None,
                router_thinking_level: None,
                analyst_model: None,
                analyst_thinking_level: None,
                prompt: String::new(),
                reviewer_ids: Some(vec![reviewer.id.clone()]),
                routing_mode: Some(trouve_protocol::CodeReviewRoutingMode::Additive),
                semantic_routing: Some(true),
                included_reviewer_ids: Some(vec![reviewer.id.clone()]),
                excluded_reviewer_ids: Some(excluded_built_ins),
                reviewer_overrides: Some(vec![trouve_protocol::ReviewerOverride {
                    reviewer_id: reviewer.id.clone(),
                    model: Some("anthropic/domain".into()),
                    thinking_level: Some("low".into()),
                    prompt_mode: trouve_protocol::ReviewerPromptMode::Replace,
                    prompt: "Use repository-specific invariants.".into(),
                }]),
            })
            .unwrap();
        store
            .update_code_review_repository(&trouve_protocol::UpdateCodeReviewRepositoryRequest {
                installation_id: 7,
                repository: "acme/unrelated".into(),
                mode: trouve_protocol::CodeReviewMode::Off,
                model: None,
                coordinator_thinking_level: None,
                router_model: None,
                router_thinking_level: None,
                analyst_model: None,
                analyst_thinking_level: None,
                prompt: String::new(),
                reviewer_ids: Some(crate::reviewers::default_reviewer_ids()),
                routing_mode: Some(trouve_protocol::CodeReviewRoutingMode::Additive),
                semantic_routing: Some(true),
                included_reviewer_ids: Some(Vec::new()),
                excluded_reviewer_ids: Some(unrelated_exclusions.clone()),
                reviewer_overrides: Some(Vec::new()),
            })
            .unwrap();
        let repositories = store.list_code_review_repositories().unwrap();
        let repository = repositories
            .iter()
            .find(|repository| repository.repository == "acme/widgets")
            .unwrap();
        assert_eq!(
            repository.reviewer_ids.as_slice(),
            std::slice::from_ref(&reviewer.id)
        );
        assert_eq!(repository.reviewer_overrides.len(), 1);
        assert_eq!(repository.included_reviewer_ids, vec![reviewer.id.clone()]);

        assert!(store.delete_custom_reviewer_profile(&reviewer.id).unwrap());
        assert!(store.list_custom_reviewer_profiles().unwrap().is_empty());
        let repositories = store.list_code_review_repositories().unwrap();
        let repository = repositories
            .iter()
            .find(|repository| repository.repository == "acme/widgets")
            .unwrap();
        assert_eq!(
            repository.reviewer_ids,
            crate::reviewers::default_reviewer_ids()
        );
        assert!(repository.included_reviewer_ids.is_empty());
        assert!(
            !repository
                .excluded_reviewer_ids
                .contains(&"correctness".into())
        );
        assert!(repository.reviewer_overrides.is_empty());
        let unrelated = repositories
            .iter()
            .find(|repository| repository.repository == "acme/unrelated")
            .unwrap();
        assert_eq!(unrelated.excluded_reviewer_ids, unrelated_exclusions);
    }

    #[test]
    fn code_review_artifacts_progress_retry_and_watermark_are_durable() {
        let store = Store::open_in_memory().unwrap();
        let reviewers = crate::reviewers::built_in_reviewers()
            .into_iter()
            .take(2)
            .collect::<Vec<_>>();
        let queued = store
            .enqueue_code_review_job(&NewCodeReviewJob {
                dedupe_key: "acme/widgets#42:artifacts".into(),
                installation_id: 7,
                repository: "acme/widgets".into(),
                pull_number: 42,
                pull_title: "Ship widgets".into(),
                pull_body: String::new(),
                pull_url: "https://github.com/acme/widgets/pull/42".into(),
                head_sha: "2222222222222222222222222222222222222222".into(),
                review_base_sha: "1111111111111111111111111111111111111111".into(),
                base_ref: "main".into(),
                head_ref: "ship".into(),
                scope: trouve_protocol::CodeReviewJobScope::Incremental,
                trigger: "automatic".into(),
                retry_of: None,
                model: Some("provider/default".into()),
                coordinator_thinking_level: Some("medium".into()),
                router_model: Some("provider/router".into()),
                router_thinking_level: Some("low".into()),
                analyst_model: None,
                analyst_thinking_level: None,
                prompt: "Review it".into(),
                reviewers,
                routing_mode: trouve_protocol::CodeReviewRoutingMode::Manual,
                semantic_routing: false,
                included_reviewer_ids: Vec::new(),
                excluded_reviewer_ids: Vec::new(),
                config_hash: "config".into(),
            })
            .unwrap()
            .unwrap();
        let running = store.claim_code_review_job().unwrap().unwrap();
        assert_eq!(running.job.id, queued.id);
        assert!(
            !store
                .prepare_code_review_batch_snapshot(&queued.id, "digest-a")
                .unwrap()
                .changed
        );
        let routing_decisions = vec![trouve_protocol::CodeReviewRoutingDecision {
            batch_index: 0,
            reviewer_id: "correctness".into(),
            reviewer_name: "Correctness".into(),
            selected: true,
            reasons: vec![trouve_protocol::CodeReviewRoutingReason {
                source: trouve_protocol::CodeReviewRoutingSource::Core,
                detail: "selected by the repository's Manual persona set".into(),
            }],
        }];
        assert_eq!(
            store
                .save_code_review_routing_decisions(&queued.id, &routing_decisions)
                .unwrap(),
            routing_decisions
        );
        let replacement = vec![trouve_protocol::CodeReviewRoutingDecision {
            selected: false,
            reasons: Vec::new(),
            ..routing_decisions[0].clone()
        }];
        assert_eq!(
            store
                .save_code_review_routing_decisions(&queued.id, &replacement)
                .unwrap(),
            routing_decisions,
            "routing is a once-only snapshot and retries must reuse it"
        );
        assert_eq!(
            store.code_review_routing_decisions(&queued.id).unwrap(),
            routing_decisions
        );
        assert!(
            !store
                .prepare_code_review_batch_snapshot(&queued.id, "digest-a")
                .unwrap()
                .changed
        );

        let task = store
            .create_code_review_task(&NewCodeReviewTask {
                job_id: queued.id.clone(),
                role: trouve_protocol::CodeReviewTaskRole::Reviewer,
                reviewer_id: Some("correctness".into()),
                reviewer_name: "Correctness".into(),
                batch_index: 0,
                batch_count: 2,
                model: Some("provider/model".into()),
                prompt: "Find defects".into(),
            })
            .unwrap();
        assert_eq!(
            task.lifecycle_stage,
            trouve_protocol::CodeReviewTaskLifecycleStage::Queued
        );
        assert!(task.last_progress_at.is_some());
        let started_task = store
            .start_code_review_task(&task.id, "se_review", "th_review", "provider/model")
            .unwrap()
            .unwrap();
        assert_eq!(
            started_task.lifecycle_stage,
            trouve_protocol::CodeReviewTaskLifecycleStage::WaitingForCapacity
        );
        let capacity = store
            .set_code_review_task_provider_wait("th_review", 17)
            .unwrap()
            .unwrap();
        assert_eq!(capacity.progress.provider_wait_ms, 17);
        assert_eq!(
            capacity.progress.lifecycle_stage,
            trouve_protocol::CodeReviewTaskLifecycleStage::StartingModel
        );
        let progress = store
            .set_code_review_task_progress(
                &task.id,
                trouve_protocol::CodeReviewTaskLifecycleStage::RunningTool,
                &CodeReviewTaskMetrics {
                    model_elapsed_ms: 23,
                    input_tokens: 100,
                    cached_input_tokens: 40,
                    output_tokens: 12,
                    tool_call_count: 2,
                },
                CodeReviewModelTiming::Started,
            )
            .unwrap()
            .unwrap();
        assert!(progress.progress.model_started_at.is_some());
        assert_eq!(progress.progress.model_elapsed_ms, 23);
        assert_eq!(progress.progress.tool_call_count, 2);
        let repair = store
            .set_code_review_task_progress(
                &task.id,
                trouve_protocol::CodeReviewTaskLifecycleStage::RepairingOutput,
                &CodeReviewTaskMetrics {
                    model_elapsed_ms: 23,
                    input_tokens: 100,
                    cached_input_tokens: 40,
                    output_tokens: 12,
                    tool_call_count: 2,
                },
                CodeReviewModelTiming::Reset,
            )
            .unwrap()
            .unwrap();
        assert!(repair.progress.model_started_at.is_none());
        let repair_capacity = store
            .set_code_review_task_provider_wait("th_review", 5)
            .unwrap()
            .unwrap();
        assert_eq!(repair_capacity.progress.provider_wait_ms, 22);
        assert_eq!(
            repair_capacity.progress.lifecycle_stage,
            trouve_protocol::CodeReviewTaskLifecycleStage::RepairingOutput
        );
        std::thread::sleep(std::time::Duration::from_millis(1));
        let repair_started = store
            .set_code_review_task_progress(
                &task.id,
                trouve_protocol::CodeReviewTaskLifecycleStage::RepairingOutput,
                &CodeReviewTaskMetrics {
                    model_elapsed_ms: 23,
                    input_tokens: 100,
                    cached_input_tokens: 40,
                    output_tokens: 12,
                    tool_call_count: 2,
                },
                CodeReviewModelTiming::Started,
            )
            .unwrap()
            .unwrap();
        assert!(repair_started.progress.model_started_at.is_some());
        assert!(repair_started.progress.model_started_at > progress.progress.model_started_at);
        assert!(
            store
                .append_code_review_task_output(
                    &task.id,
                    trouve_protocol::CodeReviewOutputStream::Assistant,
                    "candidate output",
                )
                .unwrap()
        );
        let finished_task = store
            .finish_code_review_task(&task.id, "succeeded", "", 1, "")
            .unwrap()
            .unwrap();
        assert_eq!(
            finished_task.lifecycle_stage,
            trouve_protocol::CodeReviewTaskLifecycleStage::Completed
        );
        assert_eq!(finished_task.provider_wait_ms, 22);
        assert_eq!(finished_task.model_elapsed_ms, 23);
        assert_eq!(finished_task.tool_call_count, 2);
        let partial = store.code_review_job_detail(&queued.id).unwrap().unwrap();
        assert_eq!(partial.personas[0].status, "queued");
        assert_eq!(partial.personas[0].completed_batches, 1);
        assert_eq!(partial.personas[0].total_batches, 2);
        assert_eq!(store.completed_code_review_personas(&queued.id).unwrap(), 0);
        let second_task = store
            .create_code_review_task(&NewCodeReviewTask {
                job_id: queued.id.clone(),
                role: trouve_protocol::CodeReviewTaskRole::Reviewer,
                reviewer_id: Some("correctness".into()),
                reviewer_name: "Correctness".into(),
                batch_index: 1,
                batch_count: 2,
                model: Some("provider/model".into()),
                prompt: "Find defects in the next batch".into(),
            })
            .unwrap();
        store
            .skip_code_review_task(
                &second_task.id,
                "No changed files or hunks matched this focused persona.",
            )
            .unwrap()
            .unwrap();
        assert_eq!(store.completed_code_review_personas(&queued.id).unwrap(), 1);
        assert!(
            store
                .set_code_review_job_progress(&queued.id, 1, 2)
                .unwrap()
        );
        let findings = store
            .save_code_review_result_with_adjudication(
                &queued.id,
                "One issue",
                "Fix every confirmed issue.",
                1,
                &[NewCodeReviewFinding {
                    path: "src/lib.rs".into(),
                    line: 12,
                    side: "RIGHT".into(),
                    severity: "high".into(),
                    confidence: "high".into(),
                    title: "Ignored error".into(),
                    body: "The error is ignored.".into(),
                    prompt_for_agents: "Handle the error at src/lib.rs:12.".into(),
                    sources: vec![trouve_protocol::CodeReviewFindingSource {
                        reviewer_id: "correctness".into(),
                        reviewer_name: "Correctness".into(),
                        candidate_id: "candidate-1".into(),
                        task_id: task.id.clone(),
                    }],
                }],
                &[NewCodeReviewFindingDetails {
                    evidence: trouve_protocol::CodeReviewFindingEvidence {
                        preconditions: "request reaches the changed branch".into(),
                        execution_path: "handler calls the fallible operation".into(),
                        consequence: "the failure is silently ignored".into(),
                        introduction: "the new handler drops the result".into(),
                        regression_test: "assert that the failure is returned".into(),
                        ..Default::default()
                    },
                    origin: trouve_protocol::CodeReviewFindingOrigin::NewChange,
                    theme_ids: vec!["rvth-test".into()],
                    outside_diff: true,
                }],
                &[NewCodeReviewTheme {
                    id: "rvth-test".into(),
                    root_cause: "fallible operations lack an error boundary".into(),
                    recommendation: "propagate the result through the handler".into(),
                    observation_kind: trouve_protocol::CodeReviewThemeObservationKind::New,
                    previous_finding_ids: Vec::new(),
                }],
                &[trouve_protocol::CodeReviewCandidateRejection {
                    candidate_id: "candidate-2".into(),
                    task_id: task.id.clone(),
                    reviewer_id: "correctness".into(),
                    reviewer_name: "Correctness".into(),
                    path: "src/lib.rs".into(),
                    line: 18,
                    side: "RIGHT".into(),
                    severity: "low".into(),
                    confidence: "high".into(),
                    title: "Simplify branch".into(),
                    body: "This branch could be simplified.".into(),
                    reason: "This is a non-actionable style preference.".into(),
                }],
                &[trouve_protocol::CodeReviewUnadjudicatedCandidate {
                    candidate_id: "candidate-3".into(),
                    task_id: task.id.clone(),
                    reviewer_id: "correctness".into(),
                    reviewer_name: "Correctness".into(),
                    path: "src/lib.rs".into(),
                    line: 21,
                    side: "RIGHT".into(),
                    severity: "medium".into(),
                    confidence: "high".into(),
                    title: "Unresolved behavior".into(),
                    body: "The final editor did not decide this candidate.".into(),
                }],
            )
            .unwrap();
        assert_eq!(findings.len(), 1);

        let detail = store.code_review_job_detail(&queued.id).unwrap().unwrap();
        assert_eq!(detail.job.progress.completed_reviewers, 1);
        assert_eq!(detail.tasks[0].output, "candidate output");
        assert_eq!(detail.personas[0].candidate_issue_count, 1);
        assert_eq!(detail.candidate_rejections.len(), 1);
        assert_eq!(detail.unadjudicated_candidates.len(), 1);
        assert_eq!(
            detail.unadjudicated_candidates[0].candidate_id,
            "candidate-3"
        );
        assert_eq!(detail.candidate_rejections[0].confidence, "high");
        assert_eq!(
            detail.candidate_rejections[0].reason,
            "This is a non-actionable style preference."
        );
        assert_eq!(detail.personas[0].confirmed_issue_count, 1);
        assert_eq!(detail.personas[0].status, "succeeded");
        assert_eq!(detail.findings[0].sources[0].task_id, task.id);
        assert_eq!(detail.findings[0].confidence, "high");
        assert!(detail.findings[0].outside_diff);
        assert_eq!(
            detail.findings[0].evidence.consequence,
            "the failure is silently ignored"
        );
        assert_eq!(detail.findings[0].theme_ids, ["acme/widgets#42:rvth-test"]);
        assert_eq!(detail.themes.len(), 1);
        assert_eq!(detail.themes[0].observations.len(), 1);
        assert_eq!(detail.prompt_for_agents, "Fix every confirmed issue.");
        assert_eq!(detail.routing_decisions, routing_decisions);

        let overview = store.code_review_job_overview(&queued.id).unwrap().unwrap();
        assert_eq!(overview.tasks.len(), detail.tasks.len());
        assert_eq!(overview.tasks[0].id, task.id);
        assert_eq!(overview.tasks[0].status, "succeeded");
        assert_eq!(overview.tasks[0].candidate_issue_count, 1);
        assert!(overview.tasks[0].prompt.is_empty());
        assert!(overview.tasks[0].output.is_empty());
        assert!(overview.tasks[0].thinking.is_empty());
        assert!(overview.tasks[0].tool_output.is_empty());
        assert_eq!(overview.personas.len(), detail.personas.len());
        assert_eq!(
            overview.personas[0].confirmed_issue_count,
            detail.personas[0].confirmed_issue_count
        );
        assert_eq!(overview.findings.len(), detail.findings.len());
        assert_eq!(overview.findings[0].id, detail.findings[0].id);
        assert_eq!(overview.routing_decisions, routing_decisions);

        let retained_task = store
            .code_review_task(&queued.id, &task.id)
            .unwrap()
            .unwrap();
        assert_eq!(retained_task.prompt, "Find defects");
        assert_eq!(retained_task.output, "candidate output");
        assert!(
            store
                .code_review_task("another-job", &task.id)
                .unwrap()
                .is_none()
        );

        assert_eq!(projection_retry_delay_seconds(1), 60);
        assert_eq!(projection_retry_delay_seconds(20), 6 * 60 * 60);
        store
            .record_code_review_projection_failure(&queued.id, "temporary failure", true)
            .unwrap();
        assert!(
            store
                .code_review_jobs_with_projection_errors(10)
                .unwrap()
                .is_empty()
        );
        store
            .conn
            .lock()
            .unwrap()
            .execute(
                "UPDATE code_review_jobs SET projection_retry_at = ?2 WHERE id = ?1",
                params![
                    queued.id,
                    (chrono::Utc::now() - chrono::Duration::seconds(1)).to_rfc3339()
                ],
            )
            .unwrap();
        let projection_errors = store.code_review_jobs_with_projection_errors(10).unwrap();
        assert_eq!(projection_errors.len(), 1);
        assert_eq!(projection_errors[0].id, queued.id);
        store
            .set_code_review_job_check_run(&queued.id, None, "", "")
            .unwrap();
        assert!(
            store
                .code_review_jobs_with_projection_errors(10)
                .unwrap()
                .is_empty()
        );
        store
            .record_code_review_projection_failure(&queued.id, "permanent failure", false)
            .unwrap();
        assert!(
            store
                .code_review_jobs_with_projection_errors(10)
                .unwrap()
                .is_empty()
        );

        let latest_reviewers = crate::reviewers::built_in_reviewers()
            .into_iter()
            .skip(2)
            .take(1)
            .collect::<Vec<_>>();
        let mut replacement_request =
            retry_request_for(&store, &queued.id, "acme/widgets#42:retry:latest-config");
        replacement_request.pull_title = "Ship widgets now".into();
        replacement_request.model = Some("provider/latest".into());
        replacement_request.coordinator_thinking_level = Some("high".into());
        replacement_request.router_model = Some("provider/latest-router".into());
        replacement_request.router_thinking_level = Some("medium".into());
        replacement_request.prompt = "Use the latest policy".into();
        replacement_request.reviewers = latest_reviewers;
        replacement_request.routing_mode = trouve_protocol::CodeReviewRoutingMode::Automatic;
        replacement_request.semantic_routing = true;
        replacement_request.included_reviewer_ids = vec!["performance".into()];
        replacement_request.excluded_reviewer_ids = vec!["accessibility".into()];
        replacement_request.config_hash = "latest-config".into();
        let retry = store
            .retry_code_review_job(&queued.id, &replacement_request)
            .unwrap()
            .unwrap();
        let repeated = store
            .retry_code_review_job(&queued.id, &replacement_request)
            .unwrap()
            .unwrap();
        let replacement = match retry {
            CodeReviewJobRetryOutcome::Replacement(retry) => {
                assert!(retry.predecessor_tasks.is_empty());
                retry.replacement
            }
            CodeReviewJobRetryOutcome::PublicationClaimed(_) => {
                panic!("unclaimed job should create a replacement")
            }
        };
        assert_eq!(repeated.id, replacement.id);
        assert_eq!(replacement.retry_of.as_deref(), Some(queued.id.as_str()));
        assert_eq!(
            replacement.coordinator_thinking_level.as_deref(),
            Some("high")
        );
        assert_eq!(replacement.model.as_deref(), Some("provider/latest"));
        assert_eq!(
            replacement.router_model.as_deref(),
            Some("provider/latest-router")
        );
        assert_eq!(replacement.router_thinking_level.as_deref(), Some("medium"));
        assert_eq!(replacement.progress.total_reviewers, 1);
        assert_eq!(
            store
                .code_review_job(&replacement.id)
                .unwrap()
                .unwrap()
                .prompt,
            "Use the latest policy"
        );
        let jobs = store.list_code_review_jobs(10).unwrap();
        assert_eq!(jobs.len(), 2, "a predecessor has only one replacement");
        assert_eq!(jobs[0].id, queued.id);
        assert_eq!(jobs[0].status, "running");
        assert_eq!(jobs[1].id, replacement.id);
        assert_eq!(jobs[1].status, "queued");
        let superseded_task = store
            .create_code_review_task(&NewCodeReviewTask {
                job_id: replacement.id.clone(),
                role: trouve_protocol::CodeReviewTaskRole::Reviewer,
                reviewer_id: Some("correctness".into()),
                reviewer_name: "Correctness".into(),
                batch_index: 0,
                batch_count: 1,
                model: None,
                prompt: String::new(),
            })
            .unwrap_err();
        assert!(superseded_task.to_string().contains("no longer running"));

        store
            .mark_code_review_published(
                "acme/widgets",
                42,
                "1111111111111111111111111111111111111111",
                "2222222222222222222222222222222222222222",
            )
            .unwrap();
        let watermark = store.code_review_pull_state("acme/widgets", 42).unwrap();
        assert_eq!(
            watermark.last_reviewed_head_sha,
            "2222222222222222222222222222222222222222"
        );
        assert!(watermark.last_reviewed_at.is_some());

        let stats = store
            .code_review_stats(
                trouve_protocol::CodeReviewStatsRange::All,
                Some("acme/widgets"),
            )
            .unwrap();
        assert_eq!(stats.status.running, 1);
        assert_eq!(stats.status.queued, 1);
        assert_eq!(stats.personas[0].candidate_issue_count, 1);
        assert_eq!(stats.personas[0].confirmed_issue_count, 1);
        assert_eq!(stats.personas[0].task_count, 2);
        assert_eq!(stats.personas[0].succeeded, 1);
        assert_eq!(
            stats.personas[0].succeeded
                + stats.personas[0].failed
                + stats.personas[0].cancelled
                + stats.personas[0].not_applicable,
            1
        );
        assert_eq!(stats.personas[0].not_applicable, 0);
        assert_eq!(stats.churn.pull_request_count, 0);
        assert_eq!(stats.churn.recurrence_issue_count, 0);
        assert_eq!(stats.churn.external_duplicate_count, 0);
        assert_eq!(
            stats.thread_collapse_backlog.as_ref().map(|b| b.pending),
            Some(0),
            "an idle worker reports an empty backlog"
        );
    }

    #[test]
    fn review_stats_report_the_thread_collapse_backlog() {
        let store = Store::open_in_memory().unwrap();
        let mut request = backoff_test_job_request();
        request.dedupe_key = "acme/widgets#42:collapse-backlog".into();
        let job = store.enqueue_code_review_job(&request).unwrap().unwrap();
        store.claim_code_review_job().unwrap().unwrap();
        let findings = store
            .save_code_review_result(
                &job.id,
                "One finding.",
                "",
                1,
                &[NewCodeReviewFinding {
                    path: "src/lib.rs".into(),
                    line: 3,
                    side: "RIGHT".into(),
                    severity: "high".into(),
                    confidence: "high".into(),
                    title: "Backlogged".into(),
                    body: "Awaiting thread resolution.".into(),
                    prompt_for_agents: String::new(),
                    sources: Vec::new(),
                }],
                &[],
            )
            .unwrap();
        store
            .conn
            .lock()
            .unwrap()
            .execute(
                "UPDATE code_review_findings
                 SET collapse_pending = 1, github_comment_id = 7,
                     resolved_at = '2026-08-25T00:00:00Z'
                 WHERE id = ?1",
                params![findings[0].id],
            )
            .unwrap();
        let stats = store
            .code_review_stats(trouve_protocol::CodeReviewStatsRange::All, None)
            .unwrap();
        let backlog = stats.thread_collapse_backlog.unwrap();
        assert_eq!(backlog.pending, 1);
        assert!(
            backlog
                .oldest_pending_minutes
                .is_some_and(|minutes| minutes > 0),
            "age is measured from the finding's resolution time"
        );
        // The backlog respects the repository scope like every other metric.
        let scoped = store
            .code_review_stats(
                trouve_protocol::CodeReviewStatsRange::All,
                Some("acme/widgets"),
            )
            .unwrap();
        assert_eq!(scoped.thread_collapse_backlog.unwrap().pending, 1);
        let other = store
            .code_review_stats(
                trouve_protocol::CodeReviewStatsRange::All,
                Some("acme/other"),
            )
            .unwrap();
        assert_eq!(other.thread_collapse_backlog.unwrap().pending, 0);
    }

    #[test]
    fn review_churn_stats_aggregate_classifications_and_rounds_to_clean() {
        let store = Store::open_in_memory().unwrap();
        let enqueue = |dedupe_key: &str, head_sha: &str| {
            store
                .enqueue_code_review_job(&NewCodeReviewJob {
                    dedupe_key: dedupe_key.into(),
                    installation_id: 7,
                    repository: "acme/widgets".into(),
                    pull_number: 42,
                    pull_title: "Ship widgets".into(),
                    pull_body: String::new(),
                    pull_url: "https://github.com/acme/widgets/pull/42".into(),
                    head_sha: head_sha.into(),
                    review_base_sha: "1111111111111111111111111111111111111111".into(),
                    base_ref: "main".into(),
                    head_ref: "ship".into(),
                    scope: trouve_protocol::CodeReviewJobScope::Incremental,
                    trigger: "automatic".into(),
                    retry_of: None,
                    model: Some("provider/default".into()),
                    coordinator_thinking_level: None,
                    router_model: None,
                    router_thinking_level: None,
                    analyst_model: None,
                    analyst_thinking_level: None,
                    prompt: "Review it".into(),
                    reviewers: Vec::new(),
                    routing_mode: trouve_protocol::CodeReviewRoutingMode::Manual,
                    semantic_routing: false,
                    included_reviewer_ids: Vec::new(),
                    excluded_reviewer_ids: Vec::new(),
                    config_hash: "config".into(),
                })
                .unwrap()
                .unwrap()
        };
        let legacy = enqueue(
            "acme/widgets#42:legacy-unmeasured-round",
            "1212121212121212121212121212121212121212",
        );
        assert_eq!(
            store.claim_code_review_job().unwrap().unwrap().job.id,
            legacy.id
        );
        store
            .save_code_review_result(&legacy.id, "Legacy clean result.", "", 0, &[], &[])
            .unwrap();
        store
            .finish_code_review_job(&legacy.id, "succeeded", "", "")
            .unwrap();
        store
            .conn
            .lock()
            .unwrap()
            .execute(
                "UPDATE code_review_jobs
                 SET publication_open_issue_count = NULL
                 WHERE id = ?1",
                [&legacy.id],
            )
            .unwrap();
        let first = enqueue(
            "acme/widgets#42:churn-round-1",
            "2222222222222222222222222222222222222222",
        );
        assert_eq!(
            store.claim_code_review_job().unwrap().unwrap().job.id,
            first.id
        );
        let finding = |path: &str| NewCodeReviewFinding {
            path: path.into(),
            line: 12,
            side: "RIGHT".into(),
            severity: "high".into(),
            confidence: "high".into(),
            title: "Repeated defect".into(),
            body: "The lifecycle invariant is violated.".into(),
            prompt_for_agents: "Restore the invariant.".into(),
            sources: Vec::new(),
        };
        let findings = store
            .save_code_review_result_with_themes(
                &first.id,
                "Three churn findings.",
                "Fix all three.",
                3,
                &[
                    finding("src/recurrence.rs"),
                    finding("src/regression.rs"),
                    finding("src/missed.rs"),
                ],
                &[
                    NewCodeReviewFindingDetails {
                        origin: trouve_protocol::CodeReviewFindingOrigin::Recurrence,
                        ..Default::default()
                    },
                    NewCodeReviewFindingDetails {
                        origin: trouve_protocol::CodeReviewFindingOrigin::FixRegression,
                        ..Default::default()
                    },
                    NewCodeReviewFindingDetails {
                        origin: trouve_protocol::CodeReviewFindingOrigin::PreviouslyMissed,
                        ..Default::default()
                    },
                ],
                &[],
                &[
                    trouve_protocol::CodeReviewCandidateRejection {
                        candidate_id: "external".into(),
                        task_id: "task".into(),
                        reviewer_id: "correctness".into(),
                        reviewer_name: "Correctness".into(),
                        path: "src/lib.rs".into(),
                        line: 3,
                        side: "RIGHT".into(),
                        severity: "medium".into(),
                        confidence: "high".into(),
                        title: "Duplicate".into(),
                        body: "Already reported.".into(),
                        reason: "external_duplicate: already reported by a human".into(),
                    },
                    trouve_protocol::CodeReviewCandidateRejection {
                        candidate_id: "weak".into(),
                        task_id: "task".into(),
                        reviewer_id: "correctness".into(),
                        reviewer_name: "Correctness".into(),
                        path: "src/lib.rs".into(),
                        line: 4,
                        side: "RIGHT".into(),
                        severity: "medium".into(),
                        confidence: "low".into(),
                        title: "Unproven".into(),
                        body: "Missing a reachable sequence.".into(),
                        reason: "insufficient_evidence: no reachable sequence".into(),
                    },
                    trouve_protocol::CodeReviewCandidateRejection {
                        candidate_id: "unadjudicated-legacy".into(),
                        task_id: "task".into(),
                        reviewer_id: "correctness".into(),
                        reviewer_name: "Correctness".into(),
                        path: "src/lib.rs".into(),
                        line: 5,
                        side: "RIGHT".into(),
                        severity: "medium".into(),
                        confidence: "high".into(),
                        title: "Unknown decision".into(),
                        body: "The coordinator did not adjudicate this candidate.".into(),
                        reason: format!(
                            "insufficient_evidence: The final review editor did not retain this candidate and {LEGACY_UNADJUDICATED_REASON_MARKER}."
                        ),
                    },
                ],
            )
            .unwrap();
        store
            .set_code_review_finding_publication_status(
                &findings[0].id,
                trouve_protocol::CodeReviewFindingPublicationStatus::GroupedByTheme,
            )
            .unwrap();
        assert!(store.claim_code_review_publication(&first.id).unwrap());
        store
            .record_code_review_publication(
                &first.id,
                &first.repository,
                first.pull_number,
                &first.base_ref,
                &first.head_sha,
                "https://example.test/review/1",
                false,
                &[],
            )
            .unwrap();
        store
            .finish_code_review_job(&first.id, "succeeded", "https://example.test/review/1", "")
            .unwrap();
        let prior_rejections = store
            .code_review_candidate_rejection_history_for_pull(
                &first.repository,
                first.pull_number,
                &legacy.id,
                10,
            )
            .unwrap();
        assert_eq!(prior_rejections.len(), 2);
        assert!(prior_rejections.iter().any(|rejection| {
            rejection.candidate_id == "weak"
                && rejection.reason.starts_with("insufficient_evidence:")
        }));
        assert!(
            store
                .code_review_candidate_rejection_history_for_pull(
                    &first.repository,
                    first.pull_number,
                    &first.id,
                    10,
                )
                .unwrap()
                .is_empty()
        );

        let second = enqueue(
            "acme/widgets#42:churn-round-2",
            "3333333333333333333333333333333333333333",
        );
        assert_eq!(
            store.claim_code_review_job().unwrap().unwrap().job.id,
            second.id
        );
        store
            .save_code_review_result(&second.id, "Clean.", "", 0, &[], &[])
            .unwrap();
        assert!(store.claim_code_review_publication(&second.id).unwrap());
        let resolved_finding_ids = findings
            .iter()
            .map(|finding| finding.id.as_str())
            .collect::<Vec<_>>();
        store
            .record_code_review_publication(
                &second.id,
                &second.repository,
                second.pull_number,
                &second.base_ref,
                &second.head_sha,
                "https://example.test/review/2",
                false,
                &resolved_finding_ids,
            )
            .unwrap();
        store
            .finish_code_review_job(&second.id, "succeeded", "https://example.test/review/2", "")
            .unwrap();
        let publication_open_issue_count = |job_id: &str| {
            store
                .conn
                .lock()
                .unwrap()
                .query_row(
                    "SELECT publication_open_issue_count FROM code_review_jobs WHERE id = ?1",
                    [job_id],
                    |row| row.get::<_, Option<i64>>(0),
                )
                .unwrap()
        };
        assert_eq!(publication_open_issue_count(&first.id), Some(3));
        assert_eq!(publication_open_issue_count(&second.id), Some(0));
        assert_eq!(
            store
                .code_review_job(&first.id)
                .unwrap()
                .unwrap()
                .job
                .open_issue_count,
            Some(3)
        );
        assert_eq!(
            store
                .code_review_job(&second.id)
                .unwrap()
                .unwrap()
                .job
                .open_issue_count,
            Some(0)
        );

        let stats = store
            .code_review_stats(
                trouve_protocol::CodeReviewStatsRange::All,
                Some("acme/widgets"),
            )
            .unwrap();
        assert_eq!(stats.churn.recurrence_issue_count, 1);
        assert_eq!(stats.churn.fix_regression_issue_count, 1);
        assert_eq!(stats.churn.previously_missed_issue_count, 1);
        assert_eq!(stats.churn.grouped_issue_count, 1);
        assert_eq!(stats.churn.external_duplicate_count, 1);
        assert_eq!(stats.churn.insufficient_evidence_rejection_count, 1);
        assert_eq!(stats.churn.pull_request_count, 1);
        assert_eq!(stats.churn.clean_pull_request_count, 1);
        assert_eq!(stats.churn.average_rounds_to_clean, 2.0);
        assert_eq!(stats.churn.max_rounds_to_clean, 2);

        {
            let conn = store.conn.lock().unwrap();
            conn.execute(
                "INSERT INTO code_review_candidate_rejections
                        (job_id, candidate_id, task_id, reviewer_id, reviewer_name,
                         path, line, side, severity, confidence, title, body, reason, created_at)
                 SELECT ?1, candidate_id, ?2, reviewer_id, reviewer_name,
                        path, line, side, severity, confidence, title, body, reason, created_at
                 FROM code_review_candidate_rejections
                 WHERE job_id = ?3 AND candidate_id = 'weak'",
                params![second.id, "second-task", first.id],
            )
            .unwrap();
            conn.execute(
                "UPDATE code_review_jobs
                 SET completed_at = CASE id
                         WHEN ?1 THEN '2026-08-22T00:00:00Z'
                         ELSE '2026-08-21T23:59:58Z'
                     END,
                     created_at = CASE id
                         WHEN ?1 THEN '2026-08-21T23:59:59Z'
                         ELSE '2026-08-21T23:59:57Z'
                     END
                 WHERE id IN (?1, ?2)",
                params![first.id, second.id],
            )
            .unwrap();
            conn.execute(
                "UPDATE code_review_candidate_rejections
                 SET created_at = CASE job_id
                         WHEN ?1 THEN '2026-08-22T00:00:00Z'
                         ELSE '2026-08-21T23:59:56Z'
                     END
                 WHERE job_id IN (?1, ?2)",
                params![first.id, second.id],
            )
            .unwrap();
        }
        let limited = store
            .code_review_candidate_rejection_history_for_pull(
                &first.repository,
                first.pull_number,
                &legacy.id,
                1,
            )
            .unwrap();
        assert_eq!(limited[0].task_id, "second-task");
    }

    fn publish_leveled_test_round(
        store: &Store,
        dedupe_key: &str,
        head_sha: &str,
        scope: trouve_protocol::CodeReviewJobScope,
        findings: &[(&str, &str, &str)],
        resolved_finding_ids: &[&str],
    ) -> (
        trouve_protocol::CodeReviewJob,
        Vec<trouve_protocol::CodeReviewFinding>,
    ) {
        let job = store
            .enqueue_code_review_job(&NewCodeReviewJob {
                dedupe_key: dedupe_key.into(),
                installation_id: 7,
                repository: "acme/widgets".into(),
                pull_number: 42,
                pull_title: "Ship widgets".into(),
                pull_body: String::new(),
                pull_url: "https://github.com/acme/widgets/pull/42".into(),
                head_sha: head_sha.into(),
                review_base_sha: "1111111111111111111111111111111111111111".into(),
                base_ref: "main".into(),
                head_ref: "ship".into(),
                scope,
                trigger: "automatic".into(),
                retry_of: None,
                model: Some("provider/default".into()),
                coordinator_thinking_level: None,
                router_model: None,
                router_thinking_level: None,
                analyst_model: None,
                analyst_thinking_level: None,
                prompt: "Review it".into(),
                reviewers: Vec::new(),
                routing_mode: trouve_protocol::CodeReviewRoutingMode::Manual,
                semantic_routing: false,
                included_reviewer_ids: Vec::new(),
                excluded_reviewer_ids: Vec::new(),
                config_hash: "config".into(),
            })
            .unwrap()
            .unwrap();
        assert_eq!(
            store.claim_code_review_job().unwrap().unwrap().job.id,
            job.id
        );
        let findings = findings
            .iter()
            .map(|(path, severity, confidence)| NewCodeReviewFinding {
                path: (*path).into(),
                line: 12,
                side: "RIGHT".into(),
                severity: (*severity).into(),
                confidence: (*confidence).into(),
                title: "Relocated defect".into(),
                body: "The lifecycle invariant is violated.".into(),
                prompt_for_agents: "Restore the invariant.".into(),
                sources: Vec::new(),
            })
            .collect::<Vec<_>>();
        let stored = store
            .save_code_review_result(
                &job.id,
                "Round result.",
                "",
                findings.len() as u64,
                &findings,
                &[],
            )
            .unwrap();
        assert!(store.claim_code_review_publication(&job.id).unwrap());
        store
            .record_code_review_publication(
                &job.id,
                &job.repository,
                job.pull_number,
                &job.base_ref,
                &job.head_sha,
                "https://example.test/review",
                false,
                resolved_finding_ids,
            )
            .unwrap();
        store
            .finish_code_review_job(&job.id, "succeeded", "https://example.test/review", "")
            .unwrap();
        (job, stored)
    }

    #[test]
    fn two_tier_backfill_recomputes_legacy_snapshots_once() {
        let store = Store::open_in_memory().unwrap();
        let (round, _) = publish_leveled_test_round(
            &store,
            "acme/widgets#42:tier-backfill",
            "2222222222222222222222222222222222222222",
            trouve_protocol::CodeReviewJobScope::Incremental,
            &[
                ("crates/core/src/engine.rs", "high", "high"),
                ("scripts/qualify.mjs", "low", "high"),
            ],
            &[],
        );
        // Simulate a pre-split snapshot: an all-open total with no advisory
        // column value, as deployed databases have at upgrade time.
        {
            let conn = store.conn.lock().unwrap();
            conn.execute(
                "UPDATE code_review_jobs
                 SET publication_open_issue_count = 2,
                     publication_advisory_open_issue_count = NULL
                 WHERE id = ?1",
                params![round.id],
            )
            .unwrap();
            backfill_code_review_two_tier_issue_counts(&conn).unwrap();
        }
        let migrated = store.code_review_job(&round.id).unwrap().unwrap().job;
        assert_eq!(migrated.open_issue_count, Some(1));
        assert_eq!(migrated.advisory_open_issue_count, Some(1));

        // Migrated rows are skipped on later startups: deliberate drift
        // survives a second pass, proving the backfill is one-time per row
        // rather than a full recount on every boot.
        {
            let conn = store.conn.lock().unwrap();
            conn.execute(
                "UPDATE code_review_jobs SET publication_open_issue_count = 7 WHERE id = ?1",
                params![round.id],
            )
            .unwrap();
            backfill_code_review_two_tier_issue_counts(&conn).unwrap();
        }
        assert_eq!(
            store
                .code_review_job(&round.id)
                .unwrap()
                .unwrap()
                .job
                .open_issue_count,
            Some(7)
        );
    }

    #[test]
    fn advisory_findings_accrue_as_debt_without_gating() {
        let store = Store::open_in_memory().unwrap();
        let incremental = trouve_protocol::CodeReviewJobScope::Incremental;

        // A mixed round: one blocking finding, two advisory (low severity,
        // and medium with weak evidence).
        let (round1, _) = publish_leveled_test_round(
            &store,
            "acme/widgets#42:tier-round-1",
            "2222222222222222222222222222222222222222",
            incremental,
            &[
                ("crates/core/src/engine.rs", "high", "high"),
                ("scripts/qualify.mjs", "low", "high"),
                ("scripts/qualify.mjs", "medium", "low"),
            ],
            &[],
        );
        let job = store.code_review_job(&round1.id).unwrap().unwrap().job;
        assert_eq!(
            job.open_issue_count,
            Some(1),
            "only the blocking finding gates"
        );
        assert_eq!(
            job.advisory_open_issue_count,
            Some(2),
            "advisory debt is tracked"
        );

        // Advisory-only rounds accumulate debt without ever touching the
        // blocking gate.
        let mut last = None;
        for (index, head) in ["3333", "4444", "5555"].iter().enumerate() {
            let (round, _) = publish_leveled_test_round(
                &store,
                &format!("acme/widgets#42:tier-advisory-{index}"),
                &head.repeat(10),
                incremental,
                &[("scripts/qualify.mjs", "low", "high")],
                &[],
            );
            last = Some(round.id);
        }
        let job = store.code_review_job(&last.unwrap()).unwrap().unwrap().job;
        assert_eq!(
            job.open_issue_count,
            Some(1),
            "the blocking gate is unmoved"
        );
        assert_eq!(
            job.advisory_open_issue_count,
            Some(5),
            "debt keeps accruing"
        );
    }

    #[test]
    fn scoped_review_retries_preserve_successful_reviewer_batches() {
        let store = Store::open_in_memory().unwrap();
        let reviewer = crate::reviewers::built_in_reviewers().remove(0);
        let queued = store
            .enqueue_code_review_job(&NewCodeReviewJob {
                dedupe_key: "acme/widgets#42:persona-retry".into(),
                installation_id: 7,
                repository: "acme/widgets".into(),
                pull_number: 42,
                pull_title: "Ship widgets".into(),
                pull_body: String::new(),
                pull_url: "https://github.com/acme/widgets/pull/42".into(),
                head_sha: "2222222222222222222222222222222222222222".into(),
                review_base_sha: "1111111111111111111111111111111111111111".into(),
                base_ref: "main".into(),
                head_ref: "ship".into(),
                scope: trouve_protocol::CodeReviewJobScope::Incremental,
                trigger: "automatic".into(),
                retry_of: None,
                model: Some("provider/default".into()),
                coordinator_thinking_level: None,
                router_model: None,
                router_thinking_level: None,
                analyst_model: None,
                analyst_thinking_level: None,
                prompt: "Review it".into(),
                reviewers: vec![reviewer.clone()],
                routing_mode: trouve_protocol::CodeReviewRoutingMode::Manual,
                semantic_routing: false,
                included_reviewer_ids: Vec::new(),
                excluded_reviewer_ids: Vec::new(),
                config_hash: "config".into(),
            })
            .unwrap()
            .unwrap();
        store.claim_code_review_job().unwrap().unwrap();

        let finish_batch = |batch_index: u64, status: &str, output: &str, error: &str| {
            let task = store
                .create_code_review_task(&NewCodeReviewTask {
                    job_id: queued.id.clone(),
                    role: trouve_protocol::CodeReviewTaskRole::Reviewer,
                    reviewer_id: Some(reviewer.id.clone()),
                    reviewer_name: reviewer.name.clone(),
                    batch_index,
                    batch_count: 3,
                    model: Some("provider/default".into()),
                    prompt: format!("Review batch {}", batch_index + 1),
                })
                .unwrap();
            store
                .start_code_review_task(
                    &task.id,
                    "se_review",
                    &format!("th_{batch_index}"),
                    "provider/default",
                )
                .unwrap()
                .unwrap();
            store
                .set_code_review_task_progress(
                    &task.id,
                    trouve_protocol::CodeReviewTaskLifecycleStage::RunningModel,
                    &CodeReviewTaskMetrics {
                        model_elapsed_ms: 11 + batch_index,
                        ..CodeReviewTaskMetrics::default()
                    },
                    CodeReviewModelTiming::Started,
                )
                .unwrap()
                .unwrap();
            let finished = store
                .finish_code_review_task(&task.id, status, output, 0, error)
                .unwrap()
                .unwrap();
            if matches!(status, "failed" | "cancelled") {
                assert_eq!(
                    finished.lifecycle_stage,
                    trouve_protocol::CodeReviewTaskLifecycleStage::RunningModel
                );
                assert!(finished.model_started_at.is_some());
                assert!(finished.model_elapsed_ms >= 11 + batch_index);
            }
            finished
        };
        let failed = finish_batch(0, "failed", "", "provider unavailable");
        let cancelled = finish_batch(1, "cancelled", "", "review timed out");
        let succeeded = finish_batch(2, "succeeded", r#"{"findings":[]}"#, "");
        store
            .set_code_review_job_progress(&queued.id, 1, 1)
            .unwrap();
        store
            .finish_code_review_job(&queued.id, "failed", "", "provider unavailable")
            .unwrap();

        // Simulate a terminal row persisted before active-task cleanup was
        // atomic. Persona retry must reconcile it and retain a scoped path
        // back to a valid queued attempt.
        store
            .conn
            .lock()
            .unwrap()
            .execute(
                "UPDATE code_review_tasks
                 SET status = 'running', completed_at = NULL
                 WHERE id = ?1",
                params![failed.id],
            )
            .unwrap();
        let retried = store
            .retry_code_review_persona(&queued.id, &reviewer.id)
            .unwrap()
            .unwrap();
        assert!(retried.updated_tasks.iter().any(|task| {
            task.id == failed.id
                && task.status == "cancelled"
                && task.error == "orphaned active task under failed review job"
        }));
        assert_eq!(
            retried
                .updated_tasks
                .iter()
                .filter(|task| task.status == "queued")
                .count(),
            2
        );
        assert_eq!(retried.job.id, queued.id);
        assert_eq!(retried.job.status, "queued");
        assert_eq!(retried.job.progress.completed_reviewers, 0);

        // Force identical timestamps and misleading lexical ids: the newer
        // row must still win by SQLite insertion order.
        let failed_retry_id = store
            .code_review_tasks(&queued.id)
            .unwrap()
            .into_iter()
            .find(|task| task.batch_index == 0 && task.status == "queued")
            .unwrap()
            .id;
        store
            .conn
            .lock()
            .unwrap()
            .execute(
                "UPDATE code_review_tasks
                 SET id = CASE
                       WHEN id = ?2 THEN 'rvt_z_old'
                       WHEN id = ?3 THEN 'rvt_a_new'
                       ELSE id
                     END,
                     created_at = '2026-07-27T00:00:00Z'
                 WHERE job_id = ?1 AND id IN (?2, ?3)",
                params![queued.id, failed.id, failed_retry_id],
            )
            .unwrap();

        let latest_tasks = store.latest_code_review_reviewer_tasks(&queued.id).unwrap();
        assert_eq!(
            latest_tasks
                .iter()
                .find(|task| task.batch_index == 0)
                .unwrap()
                .id,
            "rvt_a_new"
        );
        let detail = store.code_review_job_detail(&queued.id).unwrap().unwrap();
        assert_eq!(detail.tasks.len(), 5);
        assert_eq!(detail.personas[0].status, "queued");
        assert_eq!(detail.personas[0].completed_batches, 1);
        assert_eq!(detail.personas[0].total_batches, 3);
        assert_eq!(
            detail
                .tasks
                .iter()
                .filter(|task| task.batch_index == 2)
                .map(|task| task.id.as_str())
                .collect::<Vec<_>>(),
            vec![succeeded.id.as_str()]
        );

        store.claim_code_review_job().unwrap().unwrap();
        let retries = store
            .code_review_tasks(&queued.id)
            .unwrap()
            .into_iter()
            .filter(|task| task.status == "queued")
            .collect::<Vec<_>>();
        assert_eq!(
            retries
                .iter()
                .map(|task| task.batch_index)
                .collect::<Vec<_>>(),
            vec![0, 1]
        );
        for retry in retries {
            assert_ne!(retry.id, "rvt_z_old");
            assert_ne!(retry.id, cancelled.id);
            store
                .start_code_review_task(
                    &retry.id,
                    "se_retry",
                    &format!("th_retry_{}", retry.batch_index),
                    "provider/default",
                )
                .unwrap()
                .unwrap();
            store
                .finish_code_review_task(&retry.id, "succeeded", r#"{"findings":[]}"#, 0, "")
                .unwrap()
                .unwrap();
        }

        let detail = store.code_review_job_detail(&queued.id).unwrap().unwrap();
        assert_eq!(detail.personas[0].status, "succeeded");
        assert_eq!(detail.personas[0].completed_batches, 3);
        assert!(
            !store
                .code_review_job(&queued.id)
                .unwrap()
                .unwrap()
                .can_retry_final_editor
        );
        assert_eq!(store.completed_code_review_personas(&queued.id).unwrap(), 1);
        assert!(detail.tasks.iter().any(|task| task.id == "rvt_z_old"));
        assert!(detail.tasks.iter().any(|task| task.id == cancelled.id));

        store
            .set_code_review_job_progress(&queued.id, 1, 1)
            .unwrap();
        let coordinator = store
            .create_code_review_task(&NewCodeReviewTask {
                job_id: queued.id.clone(),
                role: trouve_protocol::CodeReviewTaskRole::Coordinator,
                reviewer_id: None,
                reviewer_name: "Final review editor".into(),
                batch_index: 0,
                batch_count: 1,
                model: Some("provider/default".into()),
                prompt: "Select the final findings".into(),
            })
            .unwrap();
        store
            .start_code_review_task(
                &coordinator.id,
                "se_editor",
                "th_editor",
                "provider/default",
            )
            .unwrap()
            .unwrap();
        store
            .finish_code_review_task(&coordinator.id, "failed", "", 0, "final editor timed out")
            .unwrap()
            .unwrap();
        store
            .finish_code_review_job(&queued.id, "failed", "", "final editor timed out")
            .unwrap();
        assert!(
            store
                .code_review_job(&queued.id)
                .unwrap()
                .unwrap()
                .can_retry_final_editor
        );
        let (dashboard_jobs, retryable_job_ids) = store.code_review_dashboard_jobs(100).unwrap();
        assert!(dashboard_jobs.iter().any(|job| job.id == queued.id));
        assert!(retryable_job_ids.contains(&queued.id));

        let editor_retry = store
            .retry_code_review_final_editor(&queued.id)
            .unwrap()
            .unwrap();
        assert_eq!(editor_retry.job.id, queued.id);
        assert_eq!(editor_retry.job.status, "queued");
        assert_eq!(editor_retry.job.progress.completed_reviewers, 1);
        assert_eq!(editor_retry.updated_tasks.len(), 1);
        assert_eq!(editor_retry.updated_tasks[0].status, "queued");
        let detail = store.code_review_job_detail(&queued.id).unwrap().unwrap();
        assert!(detail.tasks.iter().any(|task| task.id == coordinator.id));
        let queued_coordinator = detail
            .tasks
            .iter()
            .find(|task| {
                task.role == trouve_protocol::CodeReviewTaskRole::Coordinator
                    && task.status == "queued"
            })
            .unwrap()
            .clone();
        // A stale worker finishing after a scoped retry has already queued
        // new work must lose the guarded transition without cancelling it.
        assert!(
            store
                .finish_code_review_job(&queued.id, "failed", "", "stale worker cleanup")
                .unwrap()
                .is_none()
        );
        assert_eq!(
            store
                .code_review_task(&queued.id, &queued_coordinator.id)
                .unwrap()
                .unwrap()
                .status,
            "queued"
        );
        assert!(!detail.tasks.iter().any(|task| task.role
            == trouve_protocol::CodeReviewTaskRole::Reviewer
            && task.status == "queued"));

        store.claim_code_review_job().unwrap().unwrap();
        let started = store
            .start_code_review_task_with_prompt(
                &queued_coordinator.id,
                "se_editor_retry",
                "th_editor_retry",
                "provider/default",
                "Recomputed final findings prompt",
            )
            .unwrap()
            .unwrap();
        assert_eq!(started.prompt, "Recomputed final findings prompt");
        store
            .finish_code_review_task(&started.id, "failed", "", 0, "retry failed")
            .unwrap()
            .unwrap();

        let failed_reviewer = store
            .create_code_review_task(&NewCodeReviewTask {
                job_id: queued.id.clone(),
                role: trouve_protocol::CodeReviewTaskRole::Reviewer,
                reviewer_id: Some(reviewer.id.clone()),
                reviewer_name: reviewer.name.clone(),
                batch_index: 0,
                batch_count: 3,
                model: Some("provider/default".into()),
                prompt: "Review batch 1 again".into(),
            })
            .unwrap();
        store
            .start_code_review_task(
                &failed_reviewer.id,
                "se_reviewer_again",
                "th_reviewer_again",
                "provider/default",
            )
            .unwrap()
            .unwrap();
        store
            .finish_code_review_task(&failed_reviewer.id, "failed", "", 0, "reviewer failed")
            .unwrap()
            .unwrap();
        let leftover_router = store
            .create_code_review_task(&NewCodeReviewTask {
                job_id: queued.id.clone(),
                role: trouve_protocol::CodeReviewTaskRole::Router,
                reviewer_id: None,
                reviewer_name: "Persona router".into(),
                batch_index: 0,
                batch_count: 1,
                model: Some("provider/default".into()),
                prompt: "Route personas".into(),
            })
            .unwrap();
        store
            .start_code_review_task(
                &leftover_router.id,
                "se_router_leftover",
                "th_router_leftover",
                "provider/default",
            )
            .unwrap()
            .unwrap();
        store
            .conn
            .lock()
            .unwrap()
            .execute(
                "UPDATE code_review_tasks
                 SET model_started_at = '2026-01-01T00:00:00Z',
                     last_progress_at = '2026-01-01T00:00:10Z',
                     model_elapsed_ms = 5000
                 WHERE id = ?1",
                [&leftover_router.id],
            )
            .unwrap();
        store
            .finish_code_review_job(&queued.id, "failed", "", "retry failed")
            .unwrap();
        assert!(
            !store
                .code_review_job(&queued.id)
                .unwrap()
                .unwrap()
                .can_retry_final_editor
        );
        assert!(
            !store
                .code_review_dashboard_jobs(100)
                .unwrap()
                .1
                .contains(&queued.id)
        );
        let cancelled_router = store
            .code_review_tasks(&queued.id)
            .unwrap()
            .into_iter()
            .find(|task| task.id == leftover_router.id)
            .unwrap();
        assert_eq!(cancelled_router.status, "cancelled");
        assert!(
            cancelled_router.model_elapsed_ms > 5_000,
            "cancelling a running task must finalize its unpersisted model interval"
        );

        let error = store
            .retry_code_review_final_editor(&queued.id)
            .unwrap_err();
        assert!(error.to_string().contains("retry that persona"));

        store
            .retry_code_review_persona(&queued.id, &reviewer.id)
            .unwrap()
            .unwrap();
        store.claim_code_review_job().unwrap().unwrap();
        let reviewer_retry = store
            .code_review_tasks(&queued.id)
            .unwrap()
            .into_iter()
            .rev()
            .find(|task| {
                task.role == trouve_protocol::CodeReviewTaskRole::Reviewer
                    && task.status == "queued"
            })
            .unwrap();
        store
            .start_code_review_task(
                &reviewer_retry.id,
                "se_reviewer_fixed",
                "th_reviewer_fixed",
                "provider/default",
            )
            .unwrap()
            .unwrap();
        store
            .finish_code_review_task(&reviewer_retry.id, "succeeded", r#"{"findings":[]}"#, 0, "")
            .unwrap()
            .unwrap();
        store
            .set_code_review_job_progress(&queued.id, 1, 1)
            .unwrap();
        store
            .finish_code_review_job(&queued.id, "failed", "", "editor still failed")
            .unwrap();

        store
            .retry_code_review_final_editor(&queued.id)
            .unwrap()
            .unwrap();
        let detail = store.code_review_job_detail(&queued.id).unwrap().unwrap();
        let queued_coordinator = detail
            .tasks
            .iter()
            .rev()
            .find(|task| {
                task.role == trouve_protocol::CodeReviewTaskRole::Coordinator
                    && task.status == "queued"
            })
            .unwrap();
        let skipped = store
            .skip_code_review_task(
                &queued_coordinator.id,
                "No candidate or open finding required final editing on retry.",
            )
            .unwrap()
            .unwrap();
        assert_eq!(skipped.status, "not_applicable");

        store.claim_code_review_job().unwrap().unwrap();
        let failed_coordinator = store
            .create_code_review_task(&NewCodeReviewTask {
                job_id: queued.id.clone(),
                role: trouve_protocol::CodeReviewTaskRole::Coordinator,
                reviewer_id: None,
                reviewer_name: "Final review editor".into(),
                batch_index: 0,
                batch_count: 1,
                model: Some("provider/default".into()),
                prompt: "Try final editing again".into(),
            })
            .unwrap();
        store
            .start_code_review_task(
                &failed_coordinator.id,
                "se_editor_again",
                "th_editor_again",
                "provider/default",
            )
            .unwrap()
            .unwrap();
        store
            .finish_code_review_task(&failed_coordinator.id, "failed", "", 0, "editor failed")
            .unwrap()
            .unwrap();
        store
            .finish_code_review_job(&queued.id, "failed", "", "editor failed")
            .unwrap();
        store
            .retry_code_review_final_editor(&queued.id)
            .unwrap()
            .unwrap();
        let queued_coordinator = store
            .code_review_tasks(&queued.id)
            .unwrap()
            .into_iter()
            .rev()
            .find(|task| {
                task.role == trouve_protocol::CodeReviewTaskRole::Coordinator
                    && task.status == "queued"
            })
            .unwrap();
        let cancelled = store
            .request_code_review_job_cancel(&queued.id)
            .unwrap()
            .unwrap();
        assert_eq!(cancelled.job.status, "cancelled");
        assert!(
            store
                .code_review_job(&queued.id)
                .unwrap()
                .unwrap()
                .can_retry_final_editor
        );
        assert_eq!(cancelled.updated_tasks.len(), 1);
        assert_eq!(cancelled.updated_tasks[0].id, queued_coordinator.id);
        assert_eq!(cancelled.updated_tasks[0].status, "cancelled");
        assert_eq!(
            cancelled.updated_tasks[0].model_elapsed_ms, 0,
            "queued task cancellation must not accrue model time"
        );
        assert_eq!(
            store
                .code_review_tasks(&queued.id)
                .unwrap()
                .into_iter()
                .find(|task| task.id == queued_coordinator.id)
                .unwrap()
                .status,
            "cancelled"
        );
        let editor_retry = store
            .retry_code_review_final_editor(&queued.id)
            .unwrap()
            .unwrap();
        assert_eq!(editor_retry.job.id, queued.id);
        assert_eq!(editor_retry.job.status, "queued");
        assert_eq!(editor_retry.updated_tasks.len(), 1);
        assert_eq!(
            editor_retry.updated_tasks[0].role,
            trouve_protocol::CodeReviewTaskRole::Coordinator
        );
        assert_eq!(editor_retry.updated_tasks[0].status, "queued");
    }

